  mounted: function() {
      this.$nextTick(() => {
        this.initChart()
      })
      this.initializeData()
      this.initializeCommunication()
      // 设置定时刷新
      this.refreshInterval = setInterval(() => {
        this.refreshData()
      }, 30000) // 每30秒刷新一次
    },
  beforeDestroy: function() {
      if (this.refreshInterval) {
        clearInterval(this.refreshInterval)
      }
      
      // 清理echarts实例
      if (this.chart) {
        this.chart.dispose()
        this.chart = null
      }
      
      // 移除窗口大小改变的监听器
      window.removeEventListener('resize', this.handleResize)
      
      // 清理通信服务的事件监听器
      communicationService.off('connected', this.handleConnectionConnected);
      communicationService.off('disconnected', this.handleConnectionDisconnected);
      communicationService.off('error', this.handleCommunicationError);
      communicationService.off('event', this.handleCommunicationEvent);
      communicationService.off('sensor_data_update', this.handleSensorDataUpdate);
      communicationService.off('system_status_change', this.handleSystemStatusChange);
      communicationService.off('alarm_triggered', this.handleAlarmTriggered);
    },
  methods: {
    formatDateTime: function(date) {
      return date.toISOString().slice(0, 16)
    },
    initChart: function() {
      if (this.$refs.chartDom) {
        try {
          this.chart = echarts.init(this.$refs.chartDom)
          
          // 检查是否为倾角计传感器
          const isInclinometer = this.sensorInfo && this.sensorInfo.type === '倾角计'
          
          // 根据传感器类型动态生成图表配置
          const chartTitle = isInclinometer ? 
            `${this.sensorInfo.type} 传感器 ${this.sensorInfo.id} 角度变化曲线` : 
            `${this.sensorInfo.type || '钢表面应变计'} 传感器 ${this.sensorInfo?.id || '30780'} 应变值变化曲线`
          
          // 设置Y轴配置
          const yAxisConfig = {
            type: 'value',
            name: isInclinometer ? '角度值 (°)' : '应变值'
          }
          
          // 为倾角计设置合适的Y轴范围
          if (isInclinometer) {
            yAxisConfig.min = -5
            yAxisConfig.max = 5
          } else {
            yAxisConfig.min = 3000
            yAxisConfig.max = 3800
          }
          
          // 设置系列配置
          let seriesConfig
          if (isInclinometer) {
            // 倾角计需要两个系列
            seriesConfig = [
              {
                name: 'X角度',
                type: 'line',
                data: this.generateDefaultChartData()
              },
              {
                name: 'Y角度',
                type: 'line',
                data: this.generateDefaultChartData()
              }
            ]
          } else {
            // 其他传感器只需要一个系列
            seriesConfig = [{
              name: '应变值',
              type: 'line',
              data: this.generateDefaultChartData()
            }]
          }
          
          const option = {
            title: {
              text: chartTitle
            },
            tooltip: {
              trigger: 'axis'
            },
            xAxis: {
              type: 'time',
              name: '时间'
            },
            yAxis: yAxisConfig,
            series: seriesConfig
          }
          
          this.chart.setOption(option)
          
          // 添加窗口大小改变时的重绘
          window.addEventListener('resize', this.handleResize)
        } catch (error) {
          console.error('图表初始化失败:', error)
        }
      } else {
        console.warn('图表DOM元素未找到')
      }
    },
    onModelClick: function(id, location) {
      console.log('Model clicked:', id, location)
      
      // 从传感器ID中提取楼层信息（格式：H[floorNumber]-B[bridgeIndex]-[side]-[type]）
      const floorMatch = id.match(/H(\d+)/)
      const floorNumber = floorMatch ? parseInt(floorMatch[1]) : this.currentFloor
      
      // 从customSensorInfo中获取真实的传感器信息
      const realSensorInfo = this.customSensorInfo[id] || {}
      
      // 更新当前楼层
      const needUpdateFloor = this.currentFloor !== floorNumber
      this.currentFloor = floorNumber
      
      // 检查传感器类型，处理倾角计的特殊字段名称
      const isInclinometer = realSensorInfo.类型 === '倾角计'
      
      // 更新传感器信息，使用真实数据并去掉量程字段
      this.sensorInfo = {
        id: isInclinometer ? realSensorInfo.倾角计ID : realSensorInfo.ID || id, // 使用真实ID（倾角计使用特殊字段）
        location: isInclinometer ? realSensorInfo.倾角计位置 : realSensorInfo.位置 || location, // 使用真实位置（倾角计使用特殊字段）
        type: realSensorInfo.类型 || '未知', // 使用真实类型
        floor: floorNumber,
        status: '正常' // 模拟数据，实际应从API获取
      }
      
      // 更新选中的传感器ID，用于同步子模型组件的高亮状态
      this.selectedSensorId = id
      
      // 如果需要更新楼层，等待DOM更新完成后再执行高亮操作
      if (needUpdateFloor) {
        this.$nextTick(() => {
          // 同步高亮主模型和子模型中的相同传感器
          this.highlightSensors(id)
        })
      } else {
        // 不需要更新楼层，直接执行高亮操作
        this.highlightSensors(id)
      }
      
      // 使用真实传感器ID而不是模型ID加载数据
      this.loadSensorData(this.sensorInfo.id)
      
      // 立即更新图表标题（即使没有新数据加载）
      if (this.chart) {
        this.chart.setOption({
          title: {
            text: `${this.sensorInfo.type} 传感器 ${this.sensorInfo.id} 应变值变化曲线`
          }
        })
      }
    },
    // 同步高亮主模型和子模型中的相同传感器
    highlightSensors: function(id) {
      if (this.$refs.mainModel && typeof this.$refs.mainModel.highlightSensor === 'function') {
        this.$refs.mainModel.highlightSensor(id)
      }
      
      if (this.$refs.subModel && typeof this.$refs.subModel.highlightSensor === 'function') {
        this.$refs.subModel.highlightSensor(id)
      }
    },
    onFloorChange: function() {
      console.log('Floor changed:', this.currentFloor)
    },
    onTimeChange: function() {
      console.log('Time range changed:', this.startTime, this.endTime)
      if (this.sensorInfo.id) {
        this.loadSensorData(this.sensorInfo.id)
      }
    },
    loadSensorData: async function(sensorId) {
      // 模拟加载数据，实际应从API获取
      console.log('Loading data for sensor:', sensorId, 'from', this.startTime, 'to', this.endTime)
      try {
        // 根据传感器类型选择数据类型
        const dataType = this.sensorInfo.type === '倾角计' ? 'digangle' : 'strain'
        
        // 使用数据服务获取数据
        const data = await dataService.getSensorData(sensorId, this.startTime, this.endTime, dataType)
        console.log('Sensor data loaded:', data);
        
        this.updateChart(data)
      } catch (error) {
        console.error('加载传感器数据失败:', error)
        // 加载失败时使用模拟数据
        const mockData = this.generateMockData()
        this.updateChart(mockData)
      }
    },
    initializeData: async function() {
      try {
        await this.loadSystemInfo()
      } catch (error) {
        console.error('初始化数据失败:', error)
      }
    },
    initializeCommunication: function() {
      // 初始化通信服务
      communicationService.initialize({
        socketUrl: 'ws://localhost:8081', // 实际部署时应从配置中获取
        connectTimeout: 5000
      });
      
      // 注册事件监听器
      communicationService.on('connected', this.handleConnectionConnected);
      communicationService.on('disconnected', this.handleConnectionDisconnected);
      communicationService.on('error', this.handleCommunicationError);
      communicationService.on('event', this.handleCommunicationEvent);
      
      // 注册特定业务事件
      communicationService.on('sensor_data_update', this.handleSensorDataUpdate);
      communicationService.on('system_status_change', this.handleSystemStatusChange);
      communicationService.on('alarm_triggered', this.handleAlarmTriggered);
    },
    handleConnectionConnected: function() {
      console.log('通信连接已建立');
      this.connectionStatus = 'connected';
      this.connectionError = '';
      // 连接建立后查询最新数据
      this.queryLatestData();
    },
    handleConnectionDisconnected: function(event) {
      console.log('通信连接已断开:', event);
      this.connectionStatus = 'disconnected';
      this.connectionError = `连接已断开: ${event.reason || '未知原因'}`;
    },
    handleCommunicationError: function(error) {
      console.error('通信错误:', error);
      this.connectionError = error.message || '通信错误';
    },
    handleCommunicationEvent: function(event) {
