    handleSystemStatusChange: function(data) {
      console.log('系统状态变化:', data);
      // 更新系统状态
      if (data.status) {
        this.systemStatus = data.status;
        this.sensorCount = data.sensorCount || this.sensorCount;
        this.alarmCount = data.alarmCount || this.alarmCount;
        this.normalCount = this.sensorCount - this.alarmCount;
        this.lastUpdateTime = new Date().toLocaleString();
      }
    },
    handleAlarmTriggered: function(data) {
      console.log('告警触发:', data);
      // 处理告警
      this.handleAlarm({
        sensorId: data.sensorId,
        count: data.count || 1,
        message: data.message
      });
    },
    queryLatestData: async function() {
      try {
        // 使用通信服务查询最新数据
        await communicationService.sendQuery('system_info');
        await communicationService.sendQuery('sensor_list');
      } catch (error) {
        console.error('查询最新数据失败:', error);
        // 降级到本地数据服务
        await this.loadSystemInfo();
      }
    },
    loadSystemInfo: async function() {
      try {
        // 获取系统信息 - 使用模拟数据
        this.systemStatus = '正常运行'
        this.sensorCount = 24
        this.alarmCount = 0
        this.normalCount = this.sensorCount - this.alarmCount
        this.lastUpdateTime = new Date().toLocaleString()
      } catch (error) {
        console.error('加载系统信息失败:', error)
      }
    },
    refreshData: async function() {
      await this.loadSystemInfo()
    },
    handleAlarm: function(alarm) {
      this.alarmData = {
        title: '传感器告警',
        message: `传感器 ${alarm.sensorId} 出现 ${alarm.count} 次超限数据`
      }
      this.showAlarm = true
      // 3秒后自动关闭
      setTimeout(() => {
        this.showAlarm = false
      }, 3000)
    },
    closeAlarm: function() {
      this.showAlarm = false
    },
    handleViewChart: function(sensor) {
      this.sensorInfo = sensor
      this.loadSensorData(sensor.id)
    },
    generateDefaultChartData: function() {
      const now = new Date()
      const data = [
        [new Date(now.getTime() - 10 * 24 * 60 * 60 * 1000).getTime(), 3500],
        [new Date(now.getTime() - 8 * 24 * 60 * 60 * 1000).getTime(), 3550],
        [new Date(now.getTime() - 6 * 24 * 60 * 60 * 1000).getTime(), 3450],
        [new Date(now.getTime() - 4 * 24 * 60 * 60 * 1000).getTime(), 3600],
        [new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000).getTime(), 3550],
        [new Date(now.getTime() - 1 * 24 * 60 * 60 * 1000).getTime(), 3500],
        [now.getTime(), 3600]
      ]
      return data
    },
    generateMockData: function() {
      const data = []
      const start = new Date(this.startTime)
      const end = new Date(this.endTime)
      const hoursDiff = (end - start) / (1000 * 60 * 60)
      const pointsCount = Math.floor(hoursDiff * 2) // 每小时2个点
      
      for (let i = 0; i <= pointsCount; i++) {
        const time = new Date(start.getTime() + (i / pointsCount) * (end - start))
        const value = 1000 + Math.random() * 2000 // 1000-3000的随机值
        data.push([time.getTime(), value])
      }
      return data
    },
    updateChart: function(data) {
      if (this.chart) {
        try {
          // 检查是否为倾角计传感器
          const isInclinometer = this.sensorInfo.type === '倾角计'
          
          // 根据传感器类型动态生成图表标题和Y轴名称
          const chartTitle = isInclinometer ? 
            `${this.sensorInfo.type} 传感器 ${this.sensorInfo.id} 角度变化曲线` : 
            `${this.sensorInfo.type} 传感器 ${this.sensorInfo.id} 应变值变化曲线`
          
          const yAxisName = isInclinometer ? '角度值 (°)' : '应变值'
          
          // 对于倾角计，需要创建两个系列的数据
          let seriesData
          if (isInclinometer) {
            // 分离x和y角度数据
            const xData = data.map(point => [point[0], point[1]]) // [时间戳, x角度]
            const yData = data.map(point => [point[0], point[2]]) // [时间戳, y角度]
            
            seriesData = [
              {
                name: 'X角度',
                type: 'line',
                data: xData
              },
              {
                name: 'Y角度',
                type: 'line',
                data: yData
              }
            ]
          } else {
            // 其他传感器只需要一个系列
            seriesData = [{
              name: '应变值',
              type: 'line',
              data: data
            }]
          }
          
          this.chart.setOption({
            title: {
              text: chartTitle
            },
            yAxis: {
              name: yAxisName
            },
            series: seriesData
          })
        } catch (error) {
          console.error('图表更新失败:', error)
        }
      }
    },
    handleResize: function() {
      if (this.chart) {
        try {
          this.chart.resize()
        } catch (error) {
          console.error('图表重绘失败:', error)
        }
      }
    },
    openInterrogatorSetting: function() {
      console.log('Open interrogator setting')
    },
    collectData: function() {
      console.log('Collect data now')
      
      // 优先使用通信服务进行数据采集
      if (this.connectionStatus === 'connected') {
        communicationService.sendCommand('collect_data')
          .then(() => {
            console.log('数据采集命令已发送')
            // 不需要立即刷新，等待服务器推送更新
          })
          .catch(error => {
            console.error('发送数据采集命令失败:', error)
            // 降级到本地数据服务
            this.fallbackCollectData();
          });
      } else {
        // 降级到本地数据服务
        this.fallbackCollectData();
      }
    },
    fallbackCollectData: function() {
      // 调用数据服务进行数据采集
      dataService.collectData().then(() => {
        console.log('数据采集完成')
        this.refreshData()
      }).catch(error => {
        console.error('数据采集失败:', error)
      })
    }
  }
}
</script>

