___CSS_LOADER_EXPORT___.push([module.id, "\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\nbody {\n  font-family: 'Microsoft YaHei UI', Arial, sans-serif;\n  background-color: #f5f5f5;\n}\n.app-container {\n  width: 100%;\n  height: 100vh;\n  display: flex;\n  flex-direction: column;\n}\n.app-header {\n  background-color: #333;\n  color: white;\n  padding: 10px 20px;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  height: 60px;\n}\n.app-header h1 {\n  font-size: 20px;\n  font-weight: normal;\n}\n.header-controls {\n  display: flex;\n  gap: 10px;\n}\n.btn {\n  padding: 5px 15px;\n  background-color: #4CAF50;\n  border: none;\n  color: white;\n  cursor: pointer;\n  border-radius: 3px;\n}\n.btn:hover {\n  background-color: #45a049;\n}\n.main-content {\n  flex: 1;\n  display: flex;\n  padding: 10px;\n  gap: 10px;\n  overflow: hidden;\n}\n.main-model-section {\n  flex: 1;\n  background-color: white;\n  border-radius: 5px;\n  overflow: hidden;\n}\n.control-panel {\n  width: 36vw;\n  display: flex;\n  flex-direction: column;\n  gap: 0.8vh;\n}\n.floor-selector-container {\n  flex: 0.05;\n  background-color: white;\n  border-radius: 5px;\n  padding: 0.8vh 1vh;\n  display: flex;\n  align-items: center;\n  gap: 0.8vh;\n}\n.model-info-container {\n  display: flex;\n  /* gap: 1vw; */\n  flex: 0.4;\n  min-height: 40vh;\n}\n.sub-model-section {\n  flex: 0.7;\n  background-color: white;\n  border-radius: 5px;\n  padding: 0.8vh;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  min-width: 0;\n}\n.sensor-info {\n  flex: 0.3;\n  /* width: 11vw; */\n  background-color: white;\n  border-radius: 5px;\n  padding: 0.8vh;\n}\n.sensor-info h3 {\n  text-align: center;\n  margin-bottom: 2.5vh;\n  font-size: 1vw;\n}\n.info-item {\n  margin-bottom: 2vh;\n  display: flex;\n  align-items: center;\n}\n.info-label {\n  font-size: 0.8vw;\n  width: 3vw;\n}\n.info-value {\n  font-size: 0.8vw;\n}\n.status-normal {\n  color: #52c41a;\n  font-weight: bold;\n}\n.time-selector {\n  flex: 0.05;\n  background-color: white;\n  border-radius: 5px;\n  padding: 0.8vh;\n  display: flex;\n  align-items: center;\n  gap: 0.6vh;\n}\n.chart-container {\n  flex: 0.5;\n  background-color: white;\n  border-radius: 5px;\n  padding: 0.8vh;\n  min-height: 200px;\n}\n\n/* 头部信息 */\n.header-info {\n  display: flex;\n  align-items: center;\n  gap: 1vh;\n  font-size: 0.8vw;\n  margin-left: 1.5vw;\n}\n\n/* 连接状态样式 */\n.connection-status {\n  padding: 4px 12px;\n  border-radius: 4px;\n  font-weight: 500;\n}\n.connection-connected {\n  background-color: #1890ff;\n  color: white;\n}\n.connection-disconnected {\n  background-color: #ff4d4f;\n  color: white;\n}\n.status-indicator {\n  padding: 4px 12px;\n  border-radius: 4px;\n  font-weight: 500;\n}\n.status-normal {\n  background-color: #52c41a;\n}\n.status-alarm {\n  background-color: #f5222d;\n}\n.update-time {\n  opacity: 0.8;\n}\n\n/* 告警通知 */\n.alarm-notification {\n  position: fixed;\n  top: 70px;\n  right: -400px;\n  width: 360px;\n  background-color: white;\n  border-radius: 8px;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);\n  z-index: 2000;\n  transition: right 0.3s ease-in-out;\n}\n.alarm-notification.show {\n  right: 20px;\n}\n.alarm-content {\n  display: flex;\n  align-items: center;\n  padding: 16px;\n  gap: 12px;\n}\n.alarm-icon {\n  font-size: 24px;\n}\n.alarm-info {\n  flex: 1;\n}\n.alarm-info h4 {\n  margin: 0 0 4px 0;\n  font-size: 16px;\n  color: #333;\n}\n.alarm-info p {\n  margin: 0;\n  font-size: 14px;\n  color: #666;\n}\n.alarm-close {\n  width: 24px;\n  height: 24px;\n  border: none;\n  background: none;\n  font-size: 20px;\n  color: #999;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 4px;\n  transition: all 0.3s;\n}\n.alarm-close:hover {\n  background-color: #f0f0f0;\n  color: #666;\n}\n\n/* 响应式设计 */\n@media (max-width: 1200px) {\n.visualization-section {\n    height: 50%;\n    flex-direction: column;\n}\n.main-content {\n    height: 50%;\n}\n}\n@media (max-width: 768px) {\n.header-controls {\n    flex-direction: column;\n    gap: 5px;\n}\n.header-info {\n    margin-left: 0;\n    margin-top: 5px;\n}\n.main-content {\n    flex-direction: column;\n}\n.control-panel {\n    width: 100%;\n}\n.model-info-container {\n    flex-direction: column;\n}\n.sensor-info {\n    width: 100%;\n}\n.alarm-notification {\n    width: calc(100% - 40px);\n    right: -100%;\n}\n.alarm-notification.show {\n    right: 20px;\n}\n}\n", "",{"version":3,"sources":["webpack://./src/App.vue"],"names":[],"mappings":";AA+6DA;EACA,SAAA;EACA,UAAA;EACA,sBAAA;AACA;AAEA;EACA,oDAAA;EACA,yBAAA;AACA;AAEA;EACA,WAAA;EACA,aAAA;EACA,aAAA;EACA,sBAAA;AACA;AAEA;EACA,sBAAA;EACA,YAAA;EACA,kBAAA;EACA,aAAA;EACA,8BAAA;EACA,mBAAA;EACA,YAAA;AACA;AAEA;EACA,eAAA;EACA,mBAAA;AACA;AAEA;EACA,aAAA;EACA,SAAA;AACA;AAEA;EACA,iBAAA;EACA,yBAAA;EACA,YAAA;EACA,YAAA;EACA,eAAA;EACA,kBAAA;AACA;AAEA;EACA,yBAAA;AACA;AAEA;EACA,OAAA;EACA,aAAA;EACA,aAAA;EACA,SAAA;EACA,gBAAA;AACA;AAEA;EACA,OAAA;EACA,uBAAA;EACA,kBAAA;EACA,gBAAA;AACA;AAEA;EACA,WAAA;EACA,aAAA;EACA,sBAAA;EACA,UAAA;AACA;AAEA;EACA,UAAA;EACA,uBAAA;EACA,kBAAA;EACA,kBAAA;EACA,aAAA;EACA,mBAAA;EACA,UAAA;AACA;AAEA;EACA,aAAA;EACA,cAAA;EACA,SAAA;EACA,gBAAA;AACA;AAEA;EACA,SAAA;EACA,uBAAA;EACA,kBAAA;EACA,cAAA;EACA,aAAA;EACA,uBAAA;EACA,mBAAA;EACA,YAAA;AACA;AAEA;EACA,SAAA;EACA,iBAAA;EACA,uBAAA;EACA,kBAAA;EACA,cAAA;AACA;AAEA;EACA,kBAAA;EACA,oBAAA;EACA,cAAA;AACA;AAEA;EACA,kBAAA;EACA,aAAA;EACA,mBAAA;AACA;AAEA;EACA,gBAAA;EACA,UAAA;AACA;AAEA;EACA,gBAAA;AACA;AAEA;EACA,cAAA;EACA,iBAAA;AACA;AAEA;EACA,UAAA;EACA,uBAAA;EACA,kBAAA;EACA,cAAA;EACA,aAAA;EACA,mBAAA;EACA,UAAA;AACA;AAEA;EACA,SAAA;EACA,uBAAA;EACA,kBAAA;EACA,cAAA;EACA,iBAAA;AACA;;AAEA,SAAA;AACA;EACA,aAAA;EACA,mBAAA;EACA,QAAA;EACA,gBAAA;EACA,kBAAA;AACA;;AAEA,WAAA;AACA;EACA,iBAAA;EACA,kBAAA;EACA,gBAAA;AACA;AAEA;EACA,yBAAA;EACA,YAAA;AACA;AAEA;EACA,yBAAA;EACA,YAAA;AACA;AAEA;EACA,iBAAA;EACA,kBAAA;EACA,gBAAA;AACA;AAEA;EACA,yBAAA;AACA;AAEA