eeSubModel ref=\"subModel\" :floor=\"currentFloor\" @model-click=\"onModelClick\" :custom-sensor-info=\"customSensorInfo\" :selected-sensor-id=\"selectedSensorId\" />\n        </div>\n          <!-- 传感器信息 -->\n          <div class=\"sensor-info\">\n            <h3>传感器基本信息</h3>\n            <div class=\"info-item\">\n              <span class=\"info-label\">ID：</span>\n              <span class=\"info-value\">{{ sensorInfo.id || '30780' }}</span>\n            </div>\n            <div class=\"info-item\">\n              <span class=\"info-label\">位置：</span>\n              <span class=\"info-value\">{{ sensorInfo.location || 'GBC8-F-R-V' }}</span>\n            </div>\n            <div class=\"info-item\">\n              <span class=\"info-label\">类型：</span>\n              <span class=\"info-value\">{{ sensorInfo.type || '钢表面应变计' }}</span>\n            </div>\n            <div class=\"info-item\">\n              <span class=\"info-label\">层数：</span>\n              <span class=\"info-value\">{{ sensorInfo.floor || '8' }}</span>\n            </div>\n            <div class=\"info-item\">\n              <span class=\"info-label\">状态：</span>\n              <span class=\"info-value status-normal\">正常</span>\n            </div>\n          </div>\n        </div>\n        \n        <!-- 时间选择器 -->\n        <div class=\"time-selector\">\n          <label>请选择起止时间：</label>\n          <input type=\"datetime-local\" v-model=\"startTime\" @change=\"onTimeChange\" />\n          <span>—</span>\n          <input type=\"datetime-local\" v-model=\"endTime\" @change=\"onTimeChange\" />\n        </div>\n        \n        <!-- 图表展示 -->\n        <div class=\"chart-container\">\n          <div ref=\"chartDom\" class=\"chart\" :style=\"{ width: '100%', height: '300px' }\"></div>\n        </div>\n      </section>\n    </main>\n    \n    <!-- 告警通知 -->\n    <div class=\"alarm-notification\" v-if=\"showAlarm\" :class=\"{ show: showAlarm }\">\n      <div class=\"alarm-content\">\n        <div class=\"alarm-icon\">⚠️</div>\n        <div class=\"alarm-info\">\n          <h4>{{ alarmData.title }}</h4>\n          <p>{{ alarmData.message }}</p>\n        </div>\n        <button class=\"alarm-close\" @click=\"closeAlarm\">×</button>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script>\nimport ThreeModel from './components/ThreeModel.vue'\nimport ThreeSubModel from './components/ThreeSubModel.vue'\n// import ChartDisplay from './components/ChartDisplay.vue'\n// import DataTable from './components/DataTable.vue'  \nimport * as echarts from 'echarts'\nimport dataService from './services/dataService'\nimport communicationService from './services/communicationService'\nimport { log } from 'three'\n\nexport default {\n  name: 'App',\n  components: {\n    ThreeModel,\n    ThreeSubModel,\n    // ChartDisplay,\n    // DataTable\n  },\n  data: function() {\n    return {\n      currentFloor: 1,\n      sensorInfo: {},\n      selectedSensorId: null,\n      startTime: this.formatDateTime(new Date('2024-01-01')), // 扩大时间范围到2024年开始\n      endTime: this.formatDateTime(new Date('2026-01-01')), // 扩大时间范围到2026年\n      chart: null,\n      systemStatus: '正常运行',\n      sensorCount: 24,\n      alarmCount: 0,\n      normalCount: 24,\n      lastUpdateTime: new Date().toLocaleString(),\n      showAlarm: false,\n      alarmData: {\n        title: '',\n        message: ''\n      },\n      connectionStatus: 'disconnected',\n      connectionError: '',\n      // 自定义传感器信息，从QML文件中提取的实际传感器数据\n      customSensorInfo: {\n        // 第1层传感器映射\n        // 矮桥架 A (第一根)\n        \"H1-B1-L\": {\n          \"类型\": \"钢表面应变计\",\n          \"ID\": \"33199\",\n          \"位置\": \"GBC1-A-L\",\n          \"量程\": \"±1500με\"\n        },\n        \"H1-B1-R\": {\n          \"类型\": \"钢表面应变计\",\n          \"ID\": \"33475\",\n          \"位置\": \"GBC1-A-R\",\n          \"量程\": \"±1500με\"\n        },\n        // 长桥架 B (第二根)\n        \"H1-B2-L\": {\n          \"类型\": \"钢表面应变计\",\n          \"ID\": \"54379\",\n         