        // 第十六层传感器数据\n        \"H16-B2-L\": {\n          \"类型\": \"钢表面应变计\",\n          \"ID\": \"47778\",\n          \"位置\": \"GBC16-B-L\",\n          \"量程\": \"±1500με\"\n        },\n        \"H16-B2-R-V\": {\n          \"类型\": \"钢表面应变计\",\n          \"ID\": \"11346\",\n          \"位置\": \"GBC15-B-R-V\",\n          \"量程\": \"±1500με\"\n        },\n        \"H16-B2-R-H\": {\n          \"类型\": \"倾角计\",\n          \"倾角计位置\": \"GBC16-B-R-QJ\",\n          \"倾角计ID\": \"63836\",\n          \"量程\": \"±1500με\",\n        },\n        \"H16-B4-L\": {\n          \"类型\": \"钢表面应变计\",\n          \"ID\": \"44230\",\n          \"位置\": \"GBC16-D-L\",\n          \"量程\": \"±1500με\"\n        },\n        \"H16-B4-R-H\": {\n          \"类型\": \"倾角计\",\n          \"倾角计位置\": \"GBC16-D-R-QJ\",\n          \"倾角计ID\": \"61532\",\n          \"量程\": \"±1500με\",\n        },\n        \"H16-B6-L\": {\n          \"类型\": \"钢表面应变计\",\n          \"ID\": \"21049\",\n          \"位置\": \"GBC16-F-L\",\n          \"量程\": \"±1500με\"\n        },\n        \"H16-B6-R-V\": {\n          \"类型\": \"钢表面应变计\",\n          \"ID\": \"21049\",\n          \"位置\": \"GBC15-F-R-V\",\n          \"量程\": \"±1500με\"\n        },\n        \"H16-B6-R-H\": {\n          \"类型\": \"倾角计\",\n          \"倾角计位置\": \"GBC16-F-R-QJ\",\n          \"倾角计ID\": \"62044\",\n          \"量程\": \"±1500με\",\n        },\n        \"H16-B8-L\": {\n          \"类型\": \"钢表面应变计\",\n          \"ID\": \"52579\",\n          \"位置\": \"GBC16-H-L\",\n          \"量程\": \"±1500με\"\n        },\n        \"H16-B8-R-H\": {\n          \"类型\": \"倾角计\",\n          \"倾角计位置\": \"GBC16-H-R-QJ\",\n          \"倾角计ID\": \"63068\",\n          \"量程\": \"±1500με\",\n        },\n      }\n    }\n  },\n  mounted: function() {\n      this.$nextTick(() => {\n        this.initChart()\n      })\n      this.initializeData()\n      this.initializeCommunication()\n      // 设置定时刷新\n      this.refreshInterval = setInterval(() => {\n        this.refreshData()\n      }, 30000) // 每30秒刷新一次\n    },\n  beforeDestroy: function() {\n      if (this.refreshInterval) {\n        clearInterval(this.refreshInterval)\n      }\n      \n      // 清理echarts实例\n      if (this.chart) {\n        this.chart.dispose()\n        this.chart = null\n      }\n      \n      // 移除窗口大小改变的监听器\n      window.removeEventListener('resize', this.handleResize)\n      \n      // 清理通信服务的事件监听器\n      communicationService.off('connected', this.handleConnectionConnected);\n      communicationService.off('disconnected', this.handleConnectionDisconnected);\n      communicationService.off('error', this.handleCommunicationError);\n      communicationService.off('event', this.handleCommunicationEvent);\n      communicationService.off('sensor_data_update', this.handleSensorDataUpdate);\n      communicationService.off('system_status_change', this.handleSystemStatusChange);\n      communicationService.off('alarm_triggered', this.handleAlarmTriggered);\n    },\n  methods: {\n    formatDateTime: function(date) {\n      return date.toISOString().slice(0, 16)\n    },\n    initChart: function() {\n      if (this.$refs.chartDom) {\n        try {\n          this.chart = echarts.init(this.$refs.chartDom)\n          \n          // 检查是否为倾角计传感器\n          const isInclinometer = this.sensorInfo && this.sensorInfo.type === '倾角计'\n          \n          // 根据传感器类型动态生成图表配置\n          const chartTitle = isInclinometer ? \n            `${this.sensorInfo.type} 传感器 ${this.sensorInfo.id} 角度变化曲线` : \n            `${this.sensorInfo.type || '钢表面应变计'} 传感器 ${this.sensorInfo?.id || '30780'} 应变值变化曲线`\n          \n          // 设置Y轴配置\n          const yAxisConfig = {\n            type: 'value',\n            name: isInclinometer ? '角度值 (°)' : '应变值'\n          }\n          \n          // 为倾角计设置合适的Y轴范围\n          if (isInclinometer) {\n            yAxisConfig.min = -5\n            yAxisConfig.max = 5\n          } else {\n            yAxisConfig.min = 3000\n            yAxisConfig.max = 3800\n          }\n          \n          // 设置系列配置\n          let seriesConfig\n          if (isInclinometer) {\n            // 倾角计需要两个系列\n            seriesConfig = [\n              {\n                name: 'X角度',\n                type: 'line',\n                data: this.generateDefaultChartData()\n              },\n              {\n                name: 'Y角度',\n                type: 'line',\n                data: this.generateDefaultChartData()\n              }\n            ]\n          } else {\n            // 其他传感器只需要一个系列\n            seriesConfig = [{\n              name: '应变值',\n              type: 'line',\n              data: this.generateDefaultChartData()\n            }]\n          }\n          \n          const option = {\n            title: {\n              text: chartTitle\n            },\n            tooltip: {\n              trigger: 'axis'\n            },\n            xAxis: {\n              type: 'time',\n              name: '时间'\n            },\n            yAxis: yAxisConfig,\n            series: seriesConfig\n          }\n          \n          this.chart.setOption(option)\n          \n          // 添加窗口大小改变时的重绘\n          window.addEventListener('resize', this.handleResize)\n        } catch (error) {\n          console.error('图表初始化失败:', error)\n        }\n      } else {\n        console.warn('图表DOM元素未找到')\n      }\n    },\n    onModelClick: function(id, location) {\n      console.log('Model clicked:', id, location)\n      \n      // 从传感器ID中提取楼层信息（格式：H[floorNumber]-B[bridgeIndex]-[side]-[type]）\n      const floorMatch = id.match(/H(\\d+)/)\n      const floorNumber = floorMatch ? parseInt(floorMatch[1]) : this.currentFloor\n      \n      // 从customSensorInfo中获取真实的传感器信息\n      const realSensorInfo = this.customSensorInfo[id] || {}\n      \n      // 更新当前楼层\n      const needUpdateFloor = this.currentFloor !== floorNumber\n      this.currentFloor = floorNumber\n      \n      // 检查传感器类型，处理倾角计的特殊字段名称\n      const isInclinometer = realSensorInfo.类型 === '倾角计'\n      \n      // 更新传感器信息，使用真实数据并去掉量程字段\n      this.sensorInfo = {\n        id: isInclinometer ? realSensorInfo.倾角计ID : realSensorInfo.ID || id, // 使用真实ID（倾角计使用特殊字段）\n        location: isInclinometer ? realSensorInfo.倾角计位置 : realSensorInfo.位置 || location, // 使用真实位置（倾角计使用特殊字段）\n        type: realSensorInfo.类型 || '未知', // 使用真实类型\n        floor: floorNumber,\n        status: '正常' // 模拟数据，实际应从API获取\n      }\n      \n      // 更新选中的传感器ID，用于同步子模型组件的高亮状态\n      this.selectedSensorId = id\n      \n      // 如果需要更新楼层，等待DOM更新完成后再执行高亮操作\n      if (needUpdateFloor) {\n        this.$nextTick(() => {\n          // 同步高亮主模型和子模型中的相同传感器\n          this.highlightSensors(id)\n        })\n      } else {\n        // 不需要更新楼层，直接执行高亮操作\n        this.highlightSensors(id)\n      }\n      \n      // 使用真实传感器ID而不是模型ID加载数据\n      this.loadSensorData(this.sensorInfo.id)\n      \n      // 立即更新图表标题（即使没有新数据加载）\n      if (this.chart) {\n        this.chart.setOption({\n          title: {\n            text: `${this.sensorInfo.type} 传感器 ${this.sensorInfo.id} 应变值变化曲线`\n          }\n        })\n      }\n    },\n    // 同步高亮主模型和子模型中的相同传感器\n    highlightSensors: function(id) {\n      if (this.$refs.mainModel && typeof this.$refs.mainModel.highlightSensor === 'function') {\n        this.$refs.mainModel.highlightSensor(id)\n      }\n      \n      if (this.$refs.subModel && typeof this.$refs.subModel.highlightSensor === 'function') {\n        this.$refs.subModel.highlightSensor(id)\n      }\n    },\n    onFloorChange: function() {\n      console.log('Floor changed:', this.currentFloor)\n    },\n    onTimeChange: function() {\n      console.log('Time range changed:', this.startTime, this.endTime)\n      if (this.sensorInfo.id) {\n        this.loadSensorData(this.sensorInfo.id)\n      }\n    },\n    loadSensorData: async function(sensorId) {\n      // 模拟加载数据，实际应从API获取\n      console.log('Loading data for sensor:', sensorId, 'from', this.startTime, 'to', this.endTime)\n      try {\n        // 根据传感器类型选择数据类型\n        const dataType = this.sensorInfo.type === '倾角计' ? 'digangle' : 'strain'\n        \n        // 使用数据服务获取数据\n        const data = await dataService.getSensorData(sensorId, this.startTime, this.endTime, dataType)\n        console.log('Sensor data loaded:', data);\n        \n        this.updateChart(data)\n      } catch (error) {\n        console.error('加载传感器数据失败:', error)\n        // 加载失败时使用模拟数据\n        const mockData = this.generateMockData()\n        this.updateChart(mockData)\n      }\n    },\n    initializeData: async function() {\n      try {\n        await this.loadSystemInfo()\n      } catch (error) {\n        console.error('初始化数据失败:', error)\n      }\n    },\n    initializeCommunication: function() {\n      // 初始化通信服务\n      communicationService.initialize({\n        socketUrl: 'ws://localhost:8081', // 实际部署时应从配置中获取\n        connectTimeout: 5000\n      });\n      \n      // 注册事件监听器\n      communicationService.on('connected', this.handleConnectionConnected);\n      communicationService.on('disconnected', this.handleConnectionDisconnected);\n      communicationService.on('error', this.handleCommunicationError);\n      communicationService.on('event', this.handleCommunicationEvent);\n      \n      // 注册特定业务事件\n      communicationService.on('sensor_data_update', this.handleSensorDataUpdate);\n      communicationService.on('system_status_change', this.handleSystemStatusChange);\n      communicationService.on('alarm_triggered', this.handleAlarmTriggered);\n    },\n    handleConnectionConnected: function() {\n      console.log('通信连接已建立');\n      this.connectionStatus = 'connected';\n      this.connectionError = '';\n      // 连接建立后查询最新数据\n      this.queryLatestData();\n    },\n    handleConnectionDisconnected: function(event) {\n      console.log('通信连接已断开:', event);\n      this.connectionStatus = 'disconnected';\n      this.connectionError = `连接已断开: ${event.reason || '未知原因'}`;\n    },\n    handleCommunicationError: function(error) {\n      console.error('通信错误:', error);\n      this.connectionError = error.message || '通信错误';\n    },\n    handleCommunicationEvent: function(event) {\n      console.log('收到通信事件:', event);\n      // 处理通用事件\n    },\n    // handleSensorDataUpdate: function(data) {\n    //   console.log('传感器数据更新:', data);\n    //   // 更新传感器数据\n    //   if (data.sensorId && data.value !== undefined) {\n    //     // 通知数据表格组件更新\n    //     if (this.$refs.dataTable && typeof this.$refs.dataTable.updateSensorData === 'function') {\n    //       this.$refs.dataTable.updateSensorData({\n    //         sensorId: data.sensorId,\n    //         value: data.value,\n    //         timestamp: data.timestamp,\n    //         status: data.status === '异常' ? 'alarm' : 'normal'\n    //       });\n    //     }\n\n    //     // 如果正在查看该传感器，更新图表\n    //     if (this.sensorInfo && this.sensorInfo.id === data.sensorId) {\n    //       this.loadSensorData(data.sensorId);\n    //     }\n    //   }\n    // },\n    handleSystemStatusChange: function(data) {\n      console.log('系统状态变化:', data);\n      // 更新系统状态\n      if (data.status) {\n        this.systemStatus = data.status;\n        this.sensorCount = data.sensorCount || this.sensorCount;\n        this.alarmCount = data.alarmCount || this.alarmCount;\n        this.normalCount = this.sensorCount - this.alarmCount;\n        this.lastUpdateTime = new Date().toLocaleString();\n      }\n    },\n    handleAlarmTriggered: function(data) {\n      console.log('告警触发:', data);\n      // 处理告警\n      this.handleAlarm({\n        sensorId: data.sensorId,\n        count: data.count || 1,\n        message: data.message\n      });\n    },\n    queryLatestData: async function() {\n      try {\n        // 使用通信服务查询最新数据\n        await communicationService.sendQuery('system_info');\n        await communicationService.sendQuery('sensor_list');\n      } catch (error) {\n        console.error('查询最新数据失败:', error);\n        // 降级到本地数据服务\n        await this.loadSystemInfo();\n      }\n    },\n    loadSystemInfo: async function() {\n      try {\n        // 获取系统信息 - 使用模拟数据\n        this.systemStatus = '正常运行'\n        this.sensorCount = 24\n        this.alarmCount = 0\n        this.normalCount = this.sensorCount - this.alarmCount\n        this.lastUpdateTime = new Date().toLocaleString()\n      } catch (error) {\n        console.error('加载系统信息失败:', error)\n      }\n    },\n    refreshData: async function() {\n      await this.loadSystemInfo()\n    },\n    handleAlarm: function(alarm) {\n      this.alarmData = {\n        title: '传感器告警',\n        message: `传感器 ${alarm.sensorId} 出现 ${alarm.count} 次超限数据`\n      }\n      this.showAlarm = true\n      // 3秒后自动关闭\n      setTimeout(() => {\n        this.showAlarm = false\n      }, 3000)\n    },\n    closeAlarm: function() {\n      this.showAlarm = false\n    },\n    handleViewChart: function(sensor) {\n      this.sensorInfo = sensor\n      this.loadSensorData(sensor.id)\n    },\n    generateDefaultChartData: function() {\n      const now = new Date()\n      const data = [\n        [new Date(now.getTime() - 10 * 24 * 60 * 60 * 1000).getTime(), 3500],\n        [new Date(now.getTime() - 8 * 24 * 60 * 60 * 1000).getTime(), 3550],\n        [new Date(now.getTime() - 6 * 24 * 60 * 60 * 1000).getTime(), 3450],\n        [new Date(now.getTime() - 4 * 24 * 60 * 60 * 1000).getTime(), 3600],\n        [new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000).getTime(), 3550],\n        [new Date(now.getTime() - 1 * 24 * 60 * 60 * 1000).getTime(), 3500],\n        [now.getTime(), 3600]\n      ]\n      return data\n    },\n    generateMockData: function() {\n      const data = []\n      const start = new Date(this.startTime)\n      const end = new Date(this.endTime)\n      const hoursDiff = (end - start) / (1000 * 60 * 60)\n      const pointsCount = Math.floor(hoursDiff * 2) // 每小时2个点\n      \n      for (let i = 0; i <= pointsCount; i++) {\n        const time = new Date(start.getTime() + (i / pointsCount) * (end - start))\n        const value = 1000 + Math.random() * 2000 // 1000-3000的随机值\n        data.push([time.getTime(), value])\n      }\n      return data\n    },\n    updateChart: function(data) {\n      if (this.chart) {\n        try {\n          // 检查是否为倾角计传感器\n          const isInclinometer = this.sensorInfo.type === '倾角计'\n          \n          // 根据传感器类型动态生成图表标题和Y轴名称\n          const chartTitle = isInclinometer ? \n            `${this.sensorInfo.type} 传感器 ${this.sensorInfo.id} 角度变化曲线` : \n            `${this.sensorInfo.type} 传感器 ${this.sensorInfo.id} 应变值变化曲线`\n          \n          const yAxisName = isInclinometer ? '角度值 (°)' : '应变值'\n          \n          // 对于倾角计，需要创建两个系列的数据\n          let seriesData\n          if (isInclinometer) {\n            // 分离x和y角度数据\n            const xData = data.map(point => [point[0], point[1]]) // [时间戳, x角度]\n            const yData = data.map(point => [point[0], point[2]]) // [时间戳, y角度]\n            \n            seriesData = [\n              {\n                name: 'X角度',\n                type: 'line',\n                data: xData\n              },\n              {\n                name: 'Y角度',\n                type: 'line',\n                data: yData\n              }\n            ]\n          } else {\n            // 其他传感器只需要一个系列\n            seriesData = [{\n              name: '应变值',\n              type: 'line',\n              data: data\n            }]\n          }\n          \n          this.chart.setOption({\n            title: {\n              text: chartTitle\n            },\n            yAxis: {\n              name: yAxisName\n            },\n            series: seriesData\n          })\n        } catch (error) {\n          console.error('图表更新失败:', error)\n        }\n      }\n    },\n    handleResize: function() {\n      if (this.chart) {\n        try {\n          this.chart.resize()\n        } catch (error) {\n          console.error('图表重绘失败:', error)\n        }\n      }\n    },\n    openInterrogatorSetting: function() {\n      console.log('Open interrogator setting')\n    },\n    collectData: function() {\n      console.log('Collect data now')\n      \n      // 优先使用通信服务进行数据采集\n      if (this.connectionStatus === 'connected') {\n        communicationService.sendCommand('collect_data')\n          .then(() => {\n            console.log('数据采集命令已发送')\n            // 不需要立即刷新，等待服务器推送更新\n          })\n          .catch(error => {\n            console.error('发送数据采集命令失败:', error)\n            // 降级到本地数据服务\n            this.fallbackCollectData();\n          });\n      } else {\n        // 降级到本地数据服务\n        this.fallbackCollectData();\n      }\n    },\n    fallbackCollectData: function() {\n      // 调用数据服务进行数据采集\n      dataService.collectData().then(() => {\n        console.log('数据采集完成')\n        this.refreshData()\n      }).catch(error => {\n        console.error('数据采集失败:', error)\n      })\n    }\n  }\n}\n</script>\n\n<style>\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nbody {\n  font-family: 'Microsoft YaHei UI', Arial, sans-serif;\n  background-color: #f5f5f5;\n}\n\n.app-container {\n  width: 100%;\n  height: 100vh;\n  display: flex;\n  flex-direction: column;\n}\n\n.app-header {\n  background-color: #333;\n  color: white;\n  padding: 10px 20px;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  height: 60px;\n}\n\n.app-header h1 {\n  font-size: 20px;\n  font-weight: normal;\n}\n\n.header-controls {\n  display: flex;\n  gap: 10px;\n}\n\n.btn {\n  padding: 5px 15px;\n  background-color: #4CAF50;\n  border: none;\n  color: white;\n  cursor: pointer;\n  border-radius: 3px;\n}\n\n.btn:hover {\n  background-color: #45a049;\n}\n\n.main-content {\n  flex: 1;\n  display: flex;\n  padding: 10px;\n  gap: 10px;\n  overflow: hidden;\n}\n\n.main-model-section {\n  flex: 1;\n  background-color: white;\n  border-radius: 5px;\n  overflow: hidden;\n}\n\n.control-panel {\n  width: 36vw;\n  display: flex;\n  flex-direction: column;\n  gap: 0.8vh;\n}\n\n.floor-selector-container {\n  flex: 0.05;\n  background-color: white;\n  border-radius: 5px;\n  padding: 0.8vh 1vh;\n  display: flex;\n  align-items: center;\n  gap: 0.8vh;\n}\n\n.model-info-container {\n  display: flex;\n  /* gap: 1vw; */\n  flex: 0.4;\n  min-height: 40vh;\n}\n\n.sub-model-section {\n  flex: 0.7;\n  background-color: white;\n  border-radius: 5px;\n  padding: 0.8vh;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  min-width: 0;\n}\n\n.sensor-info {\n  flex: 0.3;\n  /* width: 11vw; */\n  background-color: white;\n  border-radius: 5px;\n  padding: 0.8vh;\n}\n\n.sensor-info h3 {\n  text-align: center;\n  margin-bottom: 2.5vh;\n  font-size: 1vw;\n}\n\n.info-item {\n  margin-bottom: 2vh;\n  display: flex;\n  align-items: center;\n}\n\n.info-label {\n  font-size: 0.8vw;\n  width: 3vw;\n}\n\n.info-value {\n  font-size: 0.8vw;\n}\n\n.status-normal {\n  color: #52c41a;\n  font-weight: bold;\n}\n\n.time-selector {\n  flex: 0.05;\n  background-color: white;\n  border-radius: 5px;\n  padding: 0.8vh;\n  display: flex;\n  align-items: center;\n  gap: 0.6vh;\n}\n\n.chart-container {\n  flex: 0.5;\n  background-color: white;\n  border-radius: 5px;\n  padding: 0.8vh;\n  min-height: 200px;\n}\n\n/* 头部信息 */\n.header-info {\n  display: flex;\n  align-items: center;\n  gap: 1vh;\n  font-size: 0.8vw;\n  margin-left: 1.5vw;\n}\n\n/* 连接状态样式 */\n.connection-status {\n  padding: 4px 12px;\n  border-radius: 4px;\n  font-weight: 500;\n}\n\n.connection-connected {\n  background-color: #1890ff;\n  color: white;\n}\n\n.connection-disconnected {\n  background-color: #ff4d4f;\n  color: white;\n}\n\n.status-indicator {\n  padding: 4px 12px;\n  border-radius: 4px;\n  font-weight: 500;\n}\n\n.status-normal {\n  background-color: #52c41a;\n}\n\n.status-alarm {\n  background-color: #f5222d;\n}\n\n.update-time {\n  opacity: 0.8;\n}\n\n/* 告警通知 */\n.alarm-notification {\n  position: fixed;\n  top: 70px;\n  right: -400px;\n  width: 360px;\n  background-color: white;\n  border-radius: 8px;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);\n  z-index: 2000;\n  transition: right 0.3s ease-in-out;\n}\n\n.alarm-notification.show {\n  right: 20px;\n}\n\n.alarm-content {\n  display: flex;\n  align-items: center;\n  padding: 16px;\n  gap: 12px;\n}\n\n.alarm-icon {\n  font-size: 24px;\n}\n\n.alarm-info {\n  flex: 1;\n}\n\n.alarm-info h4 {\n  margin: 0 0 4px 0;\n  font-size: 16px;\n  color: #333;\n}\n\n.alarm-info p {\n  margin: 0;\n  font-size: 14px;\n  color: #666;\n}\n\n.alarm-close {\n  width: 24px;\n  height: 24px;\n  border: none;\n  background: none;\n  font-size: 20px;\n  color: #999;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 4px;\n  transition: all 0.3s;\n}\n\n.alarm-close:hover {\n  background-color: #f0f0f0;\n  color: #666;\n}\n\n/* 响应式设计 */\n@media (max-width: 1200px) {\n  .visualization-section {\n    height: 50%;\n    flex-direction: column;\n  }\n  \n  .main-content {\n    height: 50%;\n  }\n}\n\n@media (max-width: 768px) {\n  .header-controls {\n    flex-direction: column;\n    gap: 5px;\n  }\n  \n  .header-info {\n    margin-left: 0;\n    margin-top: 5px;\n  }\n  \n  .main-content {\n    flex-direction: column;\n  }\n  \n  .control-panel {\n    width: 100%;\n  }\n  \n  .model-info-container {\n    flex-direction: column;\n  }\n  \n  .sensor-info {\n    width: 100%;\n  }\n  \n  .alarm-notification {\n    width: calc(100% - 40px);\n    right: -100%;\n  }\n  \n  .alarm-notification.show {\n    right: 20px;\n  }\n}\n</style>"],"sourceRoot":""}]);
