// 数据服务模块 - 处理传感器数据的获取、处理和转换

class DataService {
  constructor() {
    // 实际服务器基础URL
    this.baseUrl = 'http://172.28.176.216:3000'
    this.isMockMode = false // 连接实际服务器
  }

  /**
   * 获取传感器基本信息
   * @param {string} sensorId - 传感器ID
   * @returns {Promise<Object>} 传感器信息对象
   */
  async getSensorInfo(sensorId) {
    if (this.isMockMode) {
      return this.getMockSensorInfo(sensorId)
    }

    try {
      // 从服务器获取所有数据，然后过滤出指定传感器的信息
      const response = await fetch(this.baseUrl)
      if (!response.ok) {
        throw new Error('Network response was not ok')
      }
      const allData = await response.json()
      
      // 查找匹配的传感器数据（使用sensor_id或sensor_gbclocation）
      const sensorData = allData.find(item => 
        item.sensor_id.toString() === sensorId || 
        item.sensor_gbclocation === sensorId
      )
      
      if (!sensorData) {
        throw new Error(`Sensor ${sensorId} not found`)
      }
      
      // 转换为前端需要的格式
      return {
        id: sensorData.sensor_id.toString(),
        gbclocation: sensorData.sensor_gbclocation,
        type: sensorData.sensor_type,
        interrogatorType: sensorData.interrogator_type,
        interrogatorNumber: sensorData.interrogator_number,
        channel: sensorData.channel_number,
        status: 'normal', // 根据实际数据确定状态
        lastUpdate: sensorData.time
      }
    } catch (error) {
      console.error('Error fetching sensor info:', error)
      // 失败时返回模拟数据作为后备
      return this.getMockSensorInfo(sensorId)
    }
  }

  /**
   * 获取传感器历史数据
   * @param {string} sensorId - 传感器ID
   * @param {string} startTime - 开始时间 (ISO格式)
   * @param {string} endTime - 结束时间 (ISO格式)
   * @param {string} dataType - 数据类型 (默认: 'strain')
   * @returns {Promise<Array>} 时间序列数据数组
   */
  async getSensorData(sensorId, startTime, endTime, dataType = 'strain') {
    if (this.isMockMode) {
      return this.getMockSensorData(sensorId, startTime, endTime, dataType)
    }

    try {
      // 从服务器获取所有数据
      const response = await fetch(this.baseUrl)
      if (!response.ok) {
        throw new Error('Network response was not ok')
      }
      const allData = await response.json()
      
      // 根据dataType确定要使用的字段名
      const valueFieldMap = {
        'strain': 'sensor_strain',
        'temperature': 'sensor_temperature',
        'frequency': 'sensor_frequency',
        'sedimentation': 'sensor_sedimentationvalue',
        'humidity': 'sensor_humidity',
        'digangle_x': 'sensor_digangle_x',
        'digangle_y': 'sensor_digangle_y'
      }
      
      // 判断是否为倾角计类型
      const isInclinometer = dataType === 'digangle' || dataType === 'digangle_x' || dataType === 'digangle_y'
      
      // 过滤并处理数据
      const filteredData = allData
        .filter(item => {
          // 匹配传感器ID（支持sensor_id和sensor_gbclocation）
          const idMatch = item.sensor_id.toString() === sensorId || item.sensor_gbclocation === sensorId;
          
          // 将时间字符串转换为Date对象进行比较
          const itemTime = new Date(item.time);
          const start = new Date(startTime);
          const end = new Date(endTime);
          
          // 确保时间有效
          const timeValid = !isNaN(itemTime.getTime()) && !isNaN(start.getTime()) && !isNaN(end.getTime());
          const timeInRange = timeValid && itemTime >= start && itemTime <= end;
          
          // 确保有值 - 对于倾角计，需要x和y都有值
          let hasValue = false;
          if (isInclinometer) {
            hasValue = item['sensor_digangle_x'] !== '' && item['sensor_digangle_x'] !== null &&
                       item['sensor_digangle_y'] !== '' && item['sensor_digangle_y'] !== null;
          } else {
            const valueField = valueFieldMap[dataType] || 'sensor_strain'
            hasValue = item[valueField] !== '' && item[valueField] !== null;
          }
          
          return idMatch && timeInRange && hasValue;
        })
        .map(item => {
          const timestamp = new Date(item.time).getTime(); // 转换时间为时间戳
          
          if (isInclinometer) {
            // 对于倾角计，返回包含两个角度值的数组 [timestamp, x_value, y_value]
            return [
              timestamp,
              parseFloat(item['sensor_digangle_x']),
              parseFloat(item['sensor_digangle_y'])
            ];
          } else {
            // 对于其他传感器，返回包含单个值的数组 [timestamp, value]
            const valueField = valueFieldMap[dataType] || 'sensor_strain'
            return [timestamp, parseFloat(item[valueField])];
          }
        })
        .sort((a, b) => a[0] - b[0]) // 按时间排序
      
      return filteredData
    } catch (error) {
      console.error('Error fetching sensor data:', error)
      // 失败时返回模拟数据作为后备
      return this.getMockSensorData(sensorId, startTime, endTime, dataType)
    }
  }

  /**
   * 立即采集数据
   * @param {string} sensorId - 传感器ID (可选，为空时采集所有)
   * @returns {Promise<Object>} 采集结果
   */
  async collectData(sensorId = null) {
    // 注意：当前服务器似乎不支持POST请求的实时数据采集
    // 如果需要此功能，可能需要配置服务器端支持
    console.warn('Warning: Real-time data collection may not be supported by the current server. Using mock data.')
    return this.mockCollectData(sensorId)
  }

  /**
   * 获取所有传感器列表
   * @returns {Promise<Array>} 传感器列表
   */
  async getAllSensors() {
    if (this.isMockMode) {
      return this.getMockSensorsList()
    }

    try {
      // 从服务器获取所有数据
      const response = await fetch(this.baseUrl)
      if (!response.ok) {
        throw new Error('Network response was not ok')
      }
      const allData = await response.json()
      
      // 创建传感器ID到信息的映射，去重
      const sensorMap = new Map()
      
      allData.forEach(item => {
        const sensorId = item.sensor_id.toString()
        if (!sensorMap.has(sensorId)) {
          sensorMap.set(sensorId, {
            id: sensorId,
            gbclocation: item.sensor_gbclocation,
            type: item.sensor_type,
            interrogatorType: item.interrogator_type,
            interrogatorNumber: item.interrogator_number,
            channel: item.channel_number,
            status: 'normal', // 根据实际数据确定状态
            lastUpdate: item.time
          })
        }
      })
      
      // 转换为数组返回
      return Array.from(sensorMap.values())
    } catch (error) {
      console.error('Error fetching sensors list:', error)
      return this.getMockSensorsList()
    }
  }

  /**
   * 处理原始数据，转换为图表所需格式
   * @param {Array} rawData - 原始数据
   * @returns {Array} 处理后的时间序列数据 [[timestamp, value], ...]
   */
  processData(rawData) {
    // 假设原始数据格式为 [{timestamp: string, value: number}, ...]
    return rawData.map(item => [
      new Date(item.timestamp).getTime(),
      parseFloat(item.value)
    ])
  }

  // ===== 模拟数据方法 =====

  /**
   * 获取模拟的传感器信息
   */
  getMockSensorInfo(sensorId) {
    let type = 'H' // 默认水平传感器
    let floor = 1
    let position = 1
    let altitude = '100m'
    let location = ''

    // 解析传感器ID
    if (sensorId.startsWith('H')) {
      const parts = sensorId.split('-')
      if (parts.length >= 2) {
        floor = parseInt(parts[1])
        position = parseInt(parts[2]) || 1
        location = `水平层 ${floor}，位置 ${position}`
        altitude = `${100 + floor * 2}m`
      }
    } else if (sensorId.startsWith('T')) {
      type = 'T'
      floor = 'top'
      const parts = sensorId.split('-')
      if (parts.length >= 3) {
        position = parseInt(parts[2]) || 1
      }
      location = `库顶，位置 ${position}`
      altitude = '132m'
    } else if (sensorId.startsWith('P')) {
      type = 'P'
      floor = 'pile'
      const parts = sensorId.split('-')
      if (parts.length >= 3) {
        position = parseInt(parts[2]) || 1
      }
      location = `桩基，位置 ${position}`
      altitude = '0m'
    }

    return {
      id: sensorId,
      type: type,
      floor: floor,
      position: position,
      altitude: altitude,
      location: location,
      installationDate: '2023-01-15',
      lastCalibration: '2024-01-15',
      status: 'normal',
      unit: 'MPa',
      range: [0, 4000]
    }
  }

  /**
   * 获取模拟的传感器数据
   */
  getMockSensorData(sensorId, startTime, endTime, dataType) {
    const start = new Date(startTime)
    const end = new Date(endTime)
    const data = []
    
    // 计算时间范围的小时数
    const hoursDiff = (end - start) / (1000 * 60 * 60)
    
    // 根据时间范围决定数据点数量
    let pointsCount = 100 // 默认100个点
    if (hoursDiff < 1) {
      pointsCount = 60 // 小时内60个点（每分钟1个）
    } else if (hoursDiff < 24) {
      pointsCount = Math.min(24, Math.ceil(hoursDiff)) // 最多24个点
    } else if (hoursDiff < 24 * 30) {
      pointsCount = Math.min(30, Math.ceil(hoursDiff / 24)) // 最多30个点（每天1个）
    } else {
      pointsCount = Math.min(12, Math.ceil(hoursDiff / (24 * 30))) // 最多12个点（每月1个）
    }

    // 生成模拟数据点
    for (let i = 0; i <= pointsCount; i++) {
      const time = new Date(start.getTime() + (i / pointsCount) * (end - start))
      
      // 根据传感器类型生成不同范围的数据
      let baseValue = 1000
      let variation = 1000
      
      if (sensorId.startsWith('H')) {
        // 水平传感器数据范围
        baseValue = 1000 + (parseInt(sensorId.split('-')[1]) || 1) * 100
        variation = 1000
      } else if (sensorId.startsWith('T')) {
        // 库顶传感器数据范围
        baseValue = 1500
        variation = 800
      } else if (sensorId.startsWith('P')) {
        // 桩基传感器数据范围
        baseValue = 2000
        variation = 1200
      }
      
      // 添加一些趋势性变化
      const trendFactor = (i / pointsCount) * 200 - 100 // -100 到 100
      // 添加一些周期性变化
      const cycleFactor = Math.sin(i / 5 * Math.PI) * 300
      
      const value = baseValue + trendFactor + cycleFactor + (Math.random() - 0.5) * variation
      
      data.push([time.getTime(), Math.max(0, value)]) // 确保值不为负
    }
    
    return data
  }

  /**
   * 模拟立即采集数据
   */
  mockCollectData(sensorId = null) {
    return new Promise(resolve => {
      // 模拟网络延迟
      setTimeout(() => {
        const timestamp = new Date().toISOString()
        const sensorCount = sensorId ? 1 : Math.floor(Math.random() * 10) + 10
        
        resolve({
          success: true,
          timestamp: timestamp,
          message: `成功采集 ${sensorCount} 个传感器数据`,
          dataCount: sensorCount,
          collectedSensors: sensorId ? [sensorId] : Array.from({length: sensorCount}, (_, i) => `H${Math.floor(Math.random() * 16) + 1}-${Math.floor(Math.random() * 8) + 1}`)
        })
      }, 500)
    })
  }

  /**
   * 获取模拟的传感器列表
   */
  getMockSensorsList() {
    const sensors = []
    
    // 添加水平层传感器
    for (let floor = 1; floor <= 16; floor++) {
      for (let pos = 1; pos <= 8; pos++) {
        sensors.push({
          id: `H${floor}-${pos}`,
          type: 'H',
          floor: floor,
          position: pos,
          status: Math.random() > 0.05 ? 'normal' : 'warning',
          lastUpdate: new Date(Date.now() - Math.random() * 24 * 60 * 60 * 1000).toISOString()
        })
      }
    }
    
    // 添加库顶传感器
    for (let pos = 1; pos <= 8; pos++) {
      sensors.push({
        id: `T-1-${pos}`,
        type: 'T',
        floor: 'top',
        position: pos,
        status: Math.random() > 0.05 ? 'normal' : 'warning',
        lastUpdate: new Date(Date.now() - Math.random() * 24 * 60 * 60 * 1000).toISOString()
      })
    }
    
    // 添加桩基传感器
    for (let pos = 1; pos <= 12; pos++) {
      sensors.push({
        id: `P-1-${pos}`,
        type: 'P',
        floor: 'pile',
        position: pos,
        status: Math.random() > 0.05 ? 'normal' : 'warning',
        lastUpdate: new Date(Date.now() - Math.random() * 24 * 60 * 60 * 1000).toISOString()
      })
    }
    
    return sensors
  }

  /**
   * 分析数据趋势
   * @param {Array} data - 时间序列数据
   * @returns {Object} 趋势分析结果
   */
  analyzeTrend(data) {
    if (!data || data.length < 2) {
      return { trend: 'stable', confidence: 0 }
    }

    // 计算线性回归斜率来判断趋势
    const n = data.length
    let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0

    data.forEach(([x, y], i) => {
      sumX += i
      sumY += y
      sumXY += i * y
      sumX2 += i * i
    })

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX)
    
    // 计算数据范围来确定趋势的显著性
    const values = data.map(([_, y]) => y)
    const minValue = Math.min(...values)
    const maxValue = Math.max(...values)
    const range = maxValue - minValue

    // 根据斜率和数据范围判断趋势
    let trend = 'stable'
    let confidence = Math.abs(slope) / (range || 1) * 100
    
    if (confidence > 10) {
      trend = slope > 0 ? 'increasing' : 'decreasing'
    }

    return {
      trend,
      confidence: Math.min(100, Math.max(0, confidence)),
      average: sumY / n,
      min: minValue,
      max: maxValue,
      range: range
    }
  }

  /**
   * 设置解调仪配置
   * @param {Object} config - 配置参数
   * @returns {Promise<Object>} 操作结果
   */
  async setInterrogatorConfig(config) {
    // 注意：当前服务器似乎不支持解调仪配置的POST请求
    // 如果需要此功能，可能需要配置服务器端支持
    console.warn('Warning: Interrogator configuration may not be supported by the current server. Using mock data.')
    return this.mockSetConfig(config)
  }

  /**
   * 模拟设置配置
   */
  mockSetConfig(config) {
    return new Promise(resolve => {
      setTimeout(() => {
        resolve({
          success: true,
          timestamp: new Date().toISOString(),
          message: '解调仪配置更新成功',
          config: config
        })
      }, 300)
    })
  }
}

// 导出单例实例
export default new DataService()