<template>
  <div class="model-container" ref="modelContainer"></div>
</template>

<script>
import * as THREE from 'three'
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'
import { CSS2DRenderer, CSS2DObject } from 'three/examples/jsm/renderers/CSS2DRenderer.js'

// 修复语法错误中...
export default {
  name: 'ThreeModel',
  props: {
    // 接收自定义传感器信息
    customSensorInfo: {
      type: Object,
      default: () => ({})
    }
  },
  data: function() {
    return {
      scene: null,
      camera: null,
      renderer: null,
      labelRenderer: null, // 用于渲染CSS2D标签
      controls: null,
      mainCylinder: null,
      subModels: [], // 存储16层子模型
      bridges: [], // 存储8根桥架
      floorLabels: [], // 存储楼层标签
      // 桥架构型：H1-B1、H1-B3、H1-B5、H1-B7是矮桥架，其余是长桥架
      bridgeTypes: ['short', 'long', 'short', 'long', 'short', 'long', 'short', 'long'],
      sensors: [],
      raycaster: null,
      mouse: null,
      selectedSensor: null
    }
  },
  mounted: function() {
    this.initThree()
    this.createModel()
    this.setupEventListeners()
    this.animate()
  },
  beforeDestroy: function() {
    if (this.renderer) {
      this.renderer.dispose()
    }
    if (this.labelRenderer) {
      // 清理标签渲染器
      if (this.labelRenderer.domElement && this.labelRenderer.domElement.parentNode) {
        this.labelRenderer.domElement.parentNode.removeChild(this.labelRenderer.domElement)
      }
    }
    if (this.controls) {
      this.controls.dispose()
    }
    // 清理楼层标签
    this.floorLabels.forEach(label => {
      if (label.element && label.element.parentNode) {
        label.element.parentNode.removeChild(label.element)
      }
      if (label.parent) {
        label.parent.remove(label)
      }
    })
    window.removeEventListener('resize', this.onWindowResize)
    this.$refs.modelContainer.removeEventListener('mousedown', this.onMouseDown)
    this.$refs.modelContainer.removeEventListener('mousemove', this.onMouseMove)
    
    // 移除悬停信息显示元素
    if (this.tooltip && this.tooltip.parentNode) {
      this.tooltip.parentNode.removeChild(this.tooltip)
    }
  },
  methods: {
    initThree: function() {
      // 获取容器尺寸
      const container = this.$refs.modelContainer
      const width = container.clientWidth
      const height = container.clientHeight
      
      // 创建场景
      this.scene = new THREE.Scene()
      this.scene.background = new THREE.Color(0x2c3e50) // 深蓝色背景，更专业
      
      // 创建相机
      this.camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 1000)
      this.camera.position.set(0, 15, 60) // 调整相机位置，更好地观察长方体
      // 创建渲染器
      this.renderer = new THREE.WebGLRenderer({ antialias: true })
      this.renderer.setSize(width, height)
      this.renderer.setPixelRatio(window.devicePixelRatio)
      container.appendChild(this.renderer.domElement)
      
      // 创建标签渲染器
      this.labelRenderer = new CSS2DRenderer()
      this.labelRenderer.setSize(width, height)
      this.labelRenderer.domElement.style.position = 'absolute'
      this.labelRenderer.domElement.style.top = '0px'
      this.labelRenderer.domElement.style.pointerEvents = 'none'
      container.appendChild(this.labelRenderer.domElement)
      
      // 创建控制器
      this.controls = new OrbitControls(this.camera, this.renderer.domElement)
      this.controls.enableDamping = true
      this.controls.dampingFactor = 0.05
      // 设置控制器的目标点，这将确保相机正确查看(0, 15, 0)
      this.controls.target.set(0, 15, 0)
      // 更新控制器以应用新的目标点
      this.controls.update()
      
      // 添加光源
      const ambientLight = new THREE.AmbientLight(0xffffff, 0.6)
      this.scene.add(ambientLight)
      
      const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8)
      directionalLight.position.set(10, 20, 15)
      this.scene.add(directionalLight)
      
      // 添加辅助光源
      const topLight = new THREE.DirectionalLight(0xffffff, 0.3)
      topLight.position.set(0, 20, 0)
      this.scene.add(topLight)
      
      // 创建射线投射器
      this.raycaster = new THREE.Raycaster()
      this.mouse = new THREE.Vector2()
      
      // 添加鼠标移动事件监听器，用于悬停显示传感器信息
      this.$refs.modelContainer.addEventListener('mousemove', this.onMouseMove)
      
      // 创建悬停信息显示元素
      this.tooltip = document.createElement('div')
      this.tooltip.style.position = 'absolute'
      this.tooltip.style.backgroundColor = 'rgba(0, 0, 0, 0.8)'
      this.tooltip.style.color = 'white'
      this.tooltip.style.padding = '8px 12px'
      this.tooltip.style.borderRadius = '4px'
      this.tooltip.style.fontSize = '14px'
      this.tooltip.style.pointerEvents = 'none'
      this.tooltip.style.zIndex = '1000'
      this.tooltip.style.display = 'none'
      document.body.appendChild(this.tooltip)
      
      // // 添加辅助坐标系
      // const axesHelper = new THREE.AxesHelper(10)
      // this.scene.add(axesHelper)
    },
    createModel: function() {

      this.createMainCylinder()
      
      
      // 创建楼层分割线
      this.createFloorLines()
      
      // 添加楼层编号标识
      this.addFloorLabels()
      
      // 创建8根桥架，按长-短-长间隔顺序分布
      this.createBridges()
      
      // 创建传感器标记
      this.createSensors()
    },
    
    // createRingDividers: function() {
    //   // 创建每层子模型之间的矩形分割线（立方体形状）
    //   const subModelHeight = 20 / 16 // 主长方体高度20，分为16层
    //   const dividerWidth = 21 // 比库体稍宽
    //   const dividerDepth = 21 // 比库体稍深
    //   const dividerHeight = 0.1 // 分割线厚度
      
    //   const dividerMaterial = new THREE.MeshPhongMaterial({
    //     color: 0xffffff,
