    //     opacity: 1
    //   })
      
    //   // 创建16层子模型之间的15条分割线
    //   for (let i = 1; i <= 15; i++) {
    //     const geometry = new THREE.BoxGeometry(dividerWidth, dividerHeight, dividerDepth)
        
    //     // 创建矩形分割板
    //     const divider = new THREE.Mesh(geometry, dividerMaterial)
        
    //     // 计算位置：在两层子模型之间
    //     const yPosition = i * subModelHeight
    //     divider.position.y = yPosition
        
    //     this.scene.add(divider)
