    addModelGroups: function(subModel, floorNumber) {
      // 为每个子模型添加8组模型组，调整为长方体布局
      const groupMaterial = new THREE.MeshPhongMaterial({
        color: 0xe63946, // 专业的工业红色
        transparent: true,
        opacity: 1,
        shininess: 30
      })
      
      // 调整为8个固定位置，对应长方体的8个角附近
      const positions = [
        {x: 9, z: 9, name: '右上角'},    // 右上角
        {x: 9, z: -9, name: '右下角'},   // 右下角
        {x: -9, z: -9, name: '左下角'},  // 左下角
        {x: -9, z: 9, name: '左上角'},   // 左上角
        {x: 9, z: 0, name: '右侧'},      // 右中
        {x: -9, z: 0, name: '左侧'},     // 左中
        {x: 0, z: -9, name: '前侧'},     // 下中
        {x: 0, z: 9, name: '后侧'}       // 上中
      ]
      
      subModel.modelGroups = []
      
      positions.forEach((position, index) => {
        // 根据桥架类型确定每组模型组包含1个或2个子模型
        const bridgeType = this.bridgeTypes[index]
        const subModelCount = bridgeType === 'long' ? 2 : 1 // 长桥架对应2个子模型，短桥架对应1个
        
        for (let i = 0; i < subModelCount; i++) {
          // 创建模型组（改为长方体）
          const geometry = new THREE.BoxGeometry(0.8, 0.8, 0.8) // 立方体
          const modelGroup = new THREE.Mesh(geometry, groupMaterial)
          
          // 计算位置，多个子模型时添加横向偏移
          let x = position.x
          let z = position.z
          
          // 如果在角落位置，添加偏移避免重叠
          if (position.x !== 0 && position.z !== 0) {
            x += i * (position.x > 0 ? 0.6 : -0.6)
            z += i * (position.z > 0 ? 0.6 : -0.6)
          } else if (position.x !== 0) {
            // 左右中位置，沿z轴偏移
            z += i * 0.6
          } else {
            // 上下中位置，沿x轴偏移
            x += i * 0.6
          }
          
          modelGroup.position.set(x, 0, z) // 相对位置
          modelGroup.userData = {
            groupId: `G${floorNumber}-${index+1}-${i+1}`,
            floor: floorNumber,
            groupIndex: index + 1,
            subModelIndex: i + 1,
            bridgeType: bridgeType,
            positionName: position.name,
            description: `${floorNumber}层${position.name}第${i+1}组`
          }
          
          // 为每个模型组添加标签
          this.addModelGroupLabel(modelGroup, `${floorNumber}-${index+1}-${i+1}`)
          
          subModel.add(modelGroup)
          subModel.modelGroups.push(modelGroup)
        }
      })
    },
    
    addFloorLabels: function() {
      // 添加楼层编号标识，更新为适配新的模型高度30.3
      const subModelHeight = 30.3 / 16
      this.floorLabels = []
      
      for (let i = 0; i < 16; i++) {
        // 标签下移两层（减去2个subModelHeight）
        const height = (i * subModelHeight) + (subModelHeight / 2) - (2 * subModelHeight)
        const label = this.createLabel(`F${i+1}`, 'floor-label')
        
        // 将标签放在楼层外侧，调整位置以适应长方体模型
        const labelObj = new CSS2DObject(label)
        labelObj.position.set(-18, height, 0) // 调整X坐标使标签更靠外，更易见
        
        this.scene.add(labelObj)
        this.floorLabels.push(labelObj)
      }
      
      // 更新库顶和底部标签位置（下移两层）
      const topLabel = this.createLabel('顶部', 'top-label')
      const topLabelObj = new CSS2DObject(topLabel)
      topLabelObj.position.set(-18, 32 - (2 * subModelHeight), 0) // 调整位置适配新的高度
      this.scene.add(topLabelObj)
      this.floorLabels.push(topLabelObj)
      
      const bottomLabel = this.createLabel('底部', 'bottom-label')
      const bottomLabelObj = new CSS2DObject(bottomLabel)
      bottomLabelObj.position.set(-18, -2 - (2 * subModelHeight), 0)
      this.scene.add(bottomLabelObj)
      this.floorLabels.push(bottomLabelObj)
    },
    
    addModelGroupLabel: function(modelGroup, text) {
      // 为模型组添加小型标签
      const label = this.createLabel(text, 'model-group-label')
      const labelObj = new CSS2DObject(label)
      
      // 标签稍微高于模型组
      labelObj.position.set(0, 0.6, 0)
      
      modelGroup.add(labelObj)
    },
    
    createLabel: function(text, className) {
      // 创建CSS标签元素
      const div = document.createElement('div')
      div.className = className
      div.textContent = text
      div.style.color = '#fff'
      div.style.backgroundColor = 'rgba(0, 0, 0, 0.7)'
      div.style.padding = '2px 6px'
      div.style.borderRadius = '4px'
      div.style.fontSize = '12px'
      div.style.fontWeight = 'bold'
      div.style.textAlign = 'center'
      div.style.minWidth = '20px'
      
      // 针对不同类型的标签设置不同样式
      if (className === 'floor-label') {
        div.style.fontSize = '14px'
        div.style.padding = '4px 8px'
        div.style.backgroundColor = 'rgba(255, 69, 0, 0.8)'
      } else if (className === 'model-group-label') {
        div.style.fontSize = '10px'
        div.style.padding = '1px 3px'
        div.style.backgroundColor = 'rgba(0, 0, 255, 0.7)'
      } else if (className === 'top-label' || className === 'bottom-label') {
        div.style.fontSize = '14px'
        div.style.padding = '4px 8px'
        div.style.backgroundColor = 'rgba(70, 130, 180, 0.8)'
      }
      
      return div
    },
    
    createBridges: function() {
      // 创建8根桥架，按照长-短-长间隔顺序分布
      var bridgeWidth = 1;
      var bridgeDepth = 0.5;
      var subModelHeight = 30.3 / 16;
      var longBridgeHeight = 30;
      var shortBridgeHeight = 9.5 * subModelHeight;
      
      var bridgeMaterial = new THREE.MeshPhongMaterial({
        color: 0x666666,
        transparent: true,
        opacity: 1,
        shininess: 120, // 增加金属度
        specular: 0xa0a0a0 // 增加高光颜色，增强金属质感
      });
      
      var angles = [0, Math.PI/4 , Math.PI/2, 3*Math.PI/4, Math.PI, 5*Math.PI/4, 3*Math.PI/2, 7*Math.PI/4];
      
      this.bridges = [];
      
      for (var i = 0; i < angles.length; i++) {
        var angle = angles[i];
        var bridgeType = this.bridgeTypes[i];
        var isLongBridge = bridgeType === 'long';
        var bridgeHeight = isLongBridge ? longBridgeHeight : shortBridgeHeight;
        
        var geometry = new THREE.BoxGeometry(bridgeWidth, bridgeHeight, bridgeDepth);
        var bridge = new THREE.Mesh(geometry, bridgeMaterial);
        
        var radius = 15;
        var x = Math.cos(angle) * radius;
        var z = Math.sin(angle) * radius;
        var y = bridgeHeight / 2;
        
        bridge.position.set(x, y, z);
        // 对于矮桥架，额外旋转90度（Math.PI/2弧度）
        bridge.rotation.y = isLongBridge ? angle : angle + Math.PI / 2;
        bridge.userData = {
          bridgeId: 'B' + (i+1),
          type: isLongBridge ? 'long' : 'short',
          height: bridgeHeight
        };
        
        this.scene.add(bridge);
        this.bridges.push(bridge);
      }
    },
    createMainCylinder: function() {
      // 创建主模型，从圆柱体改为长方体
      const geometry = new THREE.CylinderGeometry( 15, 15, 30.3, 32 )
      // 移动几何体的原点到几何体的底部（向下平移高度的一半）
      geometry.translate(0, 30.3/2, 0)
      
      // 主体结构使用更专业的工业色彩
      const material = new THREE.MeshPhongMaterial({
        color: "#505c6a", // 浅灰色主体
        transparent: true,
        opacity: 1,
        shininess: 100, // 增加金属度
        specular: 0x808080 ,// 增加高光颜色，增强金属质感
        side: THREE.DoubleSide,
        shininess: 10,
        flatShading: false
      })
      
      this.mainCylinder = new THREE.Mesh(geometry, material)
      this.scene.add(this.mainCylinder)
      
      // 添加圆顶，底部与主库体顶部大小一致且贴合，圆顶底部到顶部距离为6
      const domeRadius = 15; // 与主库体顶部半径一致
      const domeHeight = 6;   // 圆顶底部到顶部的距离
      
      // 使用半球几何体，我们需要创建一个半球，其底部半径为15，高度为6
      // 对于半球来说，高度就是半径，所以我们需要计算实际的球体半径
      // 半球的高度 = 球体半径 * (1 - Math.cos(Math.PI/2)) = 球体半径
      // 但我们需要特定高度6，所以需要使用部分球体
      const thetaLength = Math.acos(1 - domeHeight / domeRadius); // 计算角度，使高度为6
      const domeGeometry = new THREE.SphereGeometry(domeRadius, 32, 16, 0, Math.PI * 2, 0, thetaLength);
      
      // 计算圆顶位置：底部与主库体顶部对齐（Y=30.3）
      // 半球的高度是从中心到顶部，所以需要计算中心位置
      const domeMaterial = new THREE.MeshPhongMaterial({
        color: "#919b9c", // 与主体相同的颜色
        transparent: true,
        opacity: 1,
        side: THREE.DoubleSide,
        shininess: 10,
        flatShading: false
      });
      
      const dome = new THREE.Mesh(domeGeometry, domeMaterial);
      // 圆顶底部与主库体顶部对齐（Y=30.3）
      // 半球的最低点在球体中心的下方，需要调整位置使底部刚好在Y=30.3
      const domeCenterY = 30.3 + domeRadius * (1 - Math.cos(thetaLength));
      dome.position.y = 19;
      dome.scale.set(1.25, 1.25, 1.25)
      this.scene.add(dome);
      this.dome = dome; // 保存圆顶引用
    },
    createFloorLines: function() {
      // 创建楼层分割线
      const lineMaterial = new THREE.MeshPhongMaterial({
        color: '#505c6a', // 白色分割线
        transparent: false,
        opacity: 1,
        shininess: 40
      })
      const subModelHeight = 30.3 / 16
      const geometry = new THREE.CylinderGeometry( 15, 15, 0.5, 32 ) // 稍微大一点的矩形板
      
      // 创建15条分割线
      for (let i = 0; i < 16; i++) {
        
        const line = new THREE.Mesh(geometry, lineMaterial)
        line.position.y = i * subModelHeight
        
        // 添加发光效果
        const outlineMaterial = new THREE.MeshBasicMaterial({
          color: "#919b9c",
          transparent: false,
          opacity: 1,
          wireframe: false
        })
        const outline = new THREE.Mesh(geometry, outlineMaterial)
        outline.scale.set(1.01, 1.05, 1.01)
        line.add(outline)
        if(i === 0) {
          line.position.y = 0
          outline.scale.set(1.04, 2.5, 1.04)
          // lineMaterial.color = ''
        }
        this.scene.add(line)
      }
    },
    createSensors: function() {
      // 创建不同的传感器几何体：竖向和横向
      // 横向传感器：宽是高的2.5倍，假设高度为0.3，则宽度为0.75
      const horizontalSensorGeometry = new THREE.BoxGeometry(0.75, 0.3, 0.3)
      // 竖向传感器：高是宽的2.5倍，假设宽度为0.3，则高度为0.75
      const verticalSensorGeometry = new THREE.BoxGeometry(0.3, 0.75, 0.3)
      const sensorMaterial = new THREE.MeshPhongMaterial({
        color: 0x2a9d8f, // 青绿色传感器
        transparent: true,
        opacity: 1,
        shininess: 50,
        emissive: 0x1a6d63, // 自发光效果
        emissiveIntensity: 0.3
      })
      
      // 创建蓝色传感器材质
      const blueSensorMaterial = new THREE.MeshPhongMaterial({
        color: 0x0066ff, // 蓝色传感器
        transparent: true,
        opacity: 1,
        shininess: 50,
        emissive: 0x0033cc, // 自发光效果
        emissiveIntensity: 0.3
      })
      
      const subModelHeight = 30.3 / 16 // 每层高度
      this.sensors = [] // 清空现有传感器
      
      // 定义8个桥架位置，每个位置有左右两侧
      const bridgePositions = [
        {angle: 0, x: 15, z: 0},     // 右侧
        {angle: Math.PI/4, x: 10.6, z: 10.6},  // 右上
        {angle: Math.PI/2, x: 0, z: 15},      // 上侧
        {angle: 3*Math.PI/4, x: -10.6, z: 10.6}, // 左上
        {angle: Math.PI, x: -15, z: 0},       // 左侧
        {angle: 5*Math.PI/4, x: -10.6, z: -10.6}, // 左下
        {angle: 3*Math.PI/2, x: 0, z: -15},     // 下侧
        {angle: 7*Math.PI/4, x: 10.6, z: -10.6}   // 右下
      ]
      
      // 遍历每个桥架
      for (let bridgeIndex = 0; bridgeIndex < this.bridgeTypes.length; bridgeIndex++) {
        const bridgeType = this.bridgeTypes[bridgeIndex]
        const isLongBridge = bridgeType === 'long'
        const position = bridgePositions[bridgeIndex]
        const angle = position.angle
        
        // 计算桥架方向的垂直方向向量
        // 对于角度angle，垂直方向是angle + Math.PI/2（顺时针旋转90度）和angle - Math.PI/2（逆时针旋转90度）
        const perpAngle1 = angle + Math.PI/2 // 右侧垂直方向
        const perpAngle2 = angle - Math.PI/2 // 左侧垂直方向
        
        const bridgeWidth = 1 // 桥架宽度
        const safeOffset = 2.75 // 进一步增加安全偏移量，确保传感器完全位于主模型外部
        // 将传感器与桥架的距离缩短1/2
        const offsetDistance = (bridgeWidth/2 + safeOffset) / 2
        
        // 以桥架为分割线，计算左右两侧位置
        // 左侧位置：在桥架的一侧（垂直于桥架方向）
        const leftX = 15 * Math.cos(angle) + offsetDistance * Math.cos(perpAngle1)
        const leftZ = 15 * Math.sin(angle) + offsetDistance * Math.sin(perpAngle1)
        
        // 右侧位置：在桥架的另一侧（垂直于桥架方向）
        const rightX = 15 * Math.cos(angle) + offsetDistance * Math.cos(perpAngle2)
        const rightZ = 15 * Math.sin(angle) + offsetDistance * Math.sin(perpAngle2)
        
        // 遍历每层
        for (let floor = 0; floor < 16; floor++) {
          // 计算每层最高Y坐标（横向传感器位置），下移楼层高度的1/2
          const horizontalY = (floor + 1) * subModelHeight - subModelHeight / 2
          // 计算竖向传感器Y坐标（比横向传感器低层高的1/3），同样下移楼层高度的1/2
          const verticalY = horizontalY - subModelHeight / 3
          
          if (isLongBridge) {
            // 长桥架逻辑
            // 左侧每层一个横向传感器（使用左侧位置）
            
            // 检查左侧横向传感器是否有匹配数据
            const leftSensorId = `H${floor+1}-B${bridgeIndex+1}-L`
            if (this.customSensorInfo[leftSensorId]) {
              const leftSensor = new THREE.Mesh(horizontalSensorGeometry, sensorMaterial.clone())
              leftSensor.position.set(leftX, horizontalY, leftZ)
              // 设置传感器旋转角度，使其与库体表面平行并绕Y轴额外旋转90°
              leftSensor.rotation.y = angle + 29*Math.PI/30
              leftSensor.userData = {
                id: leftSensorId,
                floor: floor + 1,
                bridge: bridgeIndex + 1,
                side: 'left',
                type: 'horizontal',
                originalColor: 0x2a9d8f // 存储原始颜色
              }
              this.scene.add(leftSensor)
              this.sensors.push(leftSensor)
            }
            
            // 右侧逻辑
            // 除第一层外每层一个竖向传感器（使用右侧位置）
            if (floor !== 0) {
              const rightVerticalSensorId = `H${floor+1}-B${bridgeIndex+1}-R-V`
              if (this.customSensorInfo[rightVerticalSensorId]) {
                const rightVerticalSensor = new THREE.Mesh(verticalSensorGeometry, sensorMaterial.clone())
                rightVerticalSensor.position.set(rightX, verticalY, rightZ)
                // 设置传感器旋转角度，使其与库体表面平行
                rightVerticalSensor.rotation.y = angle + Math.PI/30
                rightVerticalSensor.userData = {
                  id: rightVerticalSensorId,
                  floor: floor + 1,
                  bridge: bridgeIndex + 1,
                  side: 'right',
                  type: 'vertical',
                  originalColor: 0x2a9d8f // 存储原始颜色
                }
                this.scene.add(rightVerticalSensor)
                this.sensors.push(rightVerticalSensor)
              }
            }
            
            // 右侧第1、3、4层各有一个横向传感器（使用右侧位置）
            if (floor === 0 || floor === 2 || floor === 3) { // 0=第1层，2=第3层，3=第4层
              const rightHorizontalSensorId = `H${floor+1}-B${bridgeIndex+1}-R-H`
              if (this.customSensorInfo[rightHorizontalSensorId]) {
                const rightHorizontalSensor = new THREE.Mesh(horizontalSensorGeometry, sensorMaterial.clone())
                rightHorizontalSensor.position.set(rightX, horizontalY, rightZ)
                // 设置传感器旋转角度，使其与库体表面平行
                rightHorizontalSensor.rotation.y = angle - 29*Math.PI/30
                rightHorizontalSensor.userData = {
                  id: rightHorizontalSensorId,
                  floor: floor + 1,
                  bridge: bridgeIndex + 1,
                  side: 'right',
                  type: 'horizontal',
                  originalColor: 0x2a9d8f // 存储原始颜色
                }
                this.scene.add(rightHorizontalSensor)
                this.sensors.push(rightHorizontalSensor)
              }
            }
            
            // 右侧第七层和第十六层各有一个蓝色横向传感器
            if (floor === 6 || floor === 15) { // 6=第7层，15=第16层
              const blueSensorId = `H${floor+1}-B${bridgeIndex+1}-R-H`
              if (this.customSensorInfo[blueSensorId]) {
                const blueSensor = new THREE.Mesh(horizontalSensorGeometry, blueSensorMaterial.clone())
                blueSensor.position.set(rightX, horizontalY, rightZ)
                // 设置传感器旋转角度，使其与库体表面平行
                blueSensor.rotation.y = angle - 29*Math.PI/30
                blueSensor.userData = {
                  id: blueSensorId,
                  floor: floor + 1,
                  bridge: bridgeIndex + 1,
                  side: 'right',
                  type: 'horizontal',
                  originalColor: 0x0066ff // 存储原始颜色
                }
                this.scene.add(blueSensor)
                this.sensors.push(blueSensor)
              }
            }
          } else {
            // 矮桥架逻辑
            // 左侧只有1至9层有横向传感器（使用左侧位置）
            if (floor < 9) { // 只在0-8层创建（对应实际1-9层）
              const leftSensorId = `H${floor+1}-B${bridgeIndex+1}-L`
              if (this.customSensorInfo[leftSensorId]) {
                const leftSensor = new THREE.Mesh(horizontalSensorGeometry, sensorMaterial.clone())
                leftSensor.position.set(leftX, horizontalY, leftZ)
                // 设置传感器旋转角度，使其与库体表面平行
                leftSensor.rotation.y = angle - 16*Math.PI/30
                leftSensor.userData = {
                  id: leftSensorId,
                  floor: floor + 1,
                  bridge: bridgeIndex + 1,
                  side: 'left',
                  type: 'horizontal',
                  originalColor: 0x2a9d8f // 存储原始颜色
                }
                this.scene.add(leftSensor)
                this.sensors.push(leftSensor)
              }
            }
            
            // 右侧只有第一层有一个横向传感器（使用右侧位置）
            if (floor === 0) {
              const rightSensorId = `H${floor+1}-B${bridgeIndex+1}-R`
              if (this.customSensorInfo[rightSensorId]) {
                const rightSensor = new THREE.Mesh(horizontalSensorGeometry, sensorMaterial.clone())
                rightSensor.position.set(rightX, horizontalY, rightZ)
                // 设置传感器旋转角度，使其与库体表面平行
                rightSensor.rotation.y = angle + 16*Math.PI/30
                rightSensor.userData = {
                  id: rightSensorId,
                  floor: floor + 1,
                  bridge: bridgeIndex + 1,
                  side: 'right',
                  type: 'horizontal',
                  originalColor: 0x2a9d8f // 存储原始颜色
                }
                this.scene.add(rightSensor)
                this.sensors.push(rightSensor)
              }
            }
          }
        }
      }
      
      // 添加库顶传感器
      this.addTopAndPileSensors()
      
      // 合并自定义传感器信息
      this.mergeCustomSensorInfo()
    },
    mergeCustomSensorInfo: function() {
      this.sensors.forEach(sensor => {
        if (this.customSensorInfo[sensor.userData.id]) {
          Object.assign(sensor.userData, this.customSensorInfo[sensor.userData.id])
        }
      })
    },
    addTopAndPileSensors: function() {
      // 立方体传感器
      const sensorGeometry = new THREE.BoxGeometry(0.3, 0.3, 0.3)
      const sensorMaterial = new THREE.MeshPhongMaterial({ color: 0x00ff00 })
      

      

    },
    setupEventListeners: function() {
      window.addEventListener('resize', this.onWindowResize)
      this.$refs.modelContainer.addEventListener('mousedown', this.onMouseDown)
    },
    onWindowResize: function() {
      const container = this.$refs.modelContainer
      const width = container.clientWidth
      const height = container.clientHeight
      
      this.camera.aspect = width / height
      this.camera.updateProjectionMatrix()
      this.renderer.setSize(width, height)
      
      // 同时更新标签渲染器的尺寸
      if (this.labelRenderer) {
        this.labelRenderer.setSize(width, height)
      }
    },
    onMouseMove: function(event) {
      // 计算鼠标在归一化设备坐标系中的坐标 (-1 到 +1)
      const rect = this.$refs.modelContainer.getBoundingClientRect()
      this.mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1
      this.mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1
      
      // 更新射线投射器
      this.raycaster.setFromCamera(this.mouse, this.camera)
      
      // 计算物体和射线的焦点
      const intersects = this.raycaster.intersectObjects(this.sensors)
      
      if (intersects.length > 0) {
        const sensor = intersects[0].object
        const data = sensor.userData
        
        // 构建传感器位置信息
        let positionInfo = `层: ${data.floor}`
        if (data.bridge) positionInfo += `, 桥架: ${data.bridge}`
        if (data.side) positionInfo += `, ${data.side}`
        if (data.type) positionInfo += `, ${data.type}`
        
        // 显示悬停信息
        this.tooltip.style.display = 'block'
        
        // 构建悬停信息HTML，显示所有自定义字段
        let tooltipContent = `<div><strong>编号:</strong> ${data.编号 || data.id}</div>`
        
        // 显示所有自定义字段
        for (const [key, value] of Object.entries(data)) {
          if (key !== 'id' && key !== 'floor' && key !== 'bridge' && key !== 'side' && key !== 'type' && key !== 'originalColor') {
            tooltipContent += `<div><strong>${key}:</strong> ${value}</div>`
          }
        }
        this.tooltip.innerHTML = tooltipContent
        
        // 设置悬停信息的位置
        this.tooltip.style.left = `${event.clientX + 10}px`
        this.tooltip.style.top = `${event.clientY + 10}px`
      } else {
        // 隐藏悬停信息
        this.tooltip.style.display = 'none'
      }
    },
    onMouseDown: function(event) {
      // 计算鼠标在归一化设备坐标系中的坐标 (-1 到 +1)
      const rect = this.$refs.modelContainer.getBoundingClientRect()
      this.mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1
      this.mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1
      
      // 更新射线投射器
      this.raycaster.setFromCamera(this.mouse, this.camera)
      
      // 计算物体和射线的焦点
      const intersects = this.raycaster.intersectObjects(this.sensors)
      
      if (intersects.length > 0) {
        // 高亮当前选中的传感器
        this.highlightSensor(intersects[0].object.userData.id)
        
        // 触发点击事件
        this.$emit('model-click', 
          this.selectedSensor.userData.id,
          `位置: ${this.selectedSensor.userData.floor} 层 ${this.selectedSensor.userData.angle || this.selectedSensor.userData.position} 号`
        )
      }
    },
    // 高亮指定ID的传感器
    highlightSensor: function(sensorId) {
      // 找到指定ID的传感器
      const sensor = this.sensors.find(s => s.userData.id === sensorId)
      
      if (sensor) {
        // 取消之前选中的传感器高亮
        if (this.selectedSensor) {
          // 恢复原始颜色
          this.selectedSensor.material.color.set(this.selectedSensor.userData.originalColor)
        }
        
        // 高亮当前选中的传感器
        this.selectedSensor = sensor
        this.selectedSensor.material.color.set(0xff0000)
        
        return true // 返回高亮成功
      }
      
      return false // 返回高亮失败（未找到传感器）
    },
    animate: function() {
      requestAnimationFrame(() => this.animate())
      
      // 更新控制器
      this.controls.update()
      
      // 渲染场景
      this.renderer.render(this.scene, this.camera)
      
      // 渲染标签
      if (this.labelRenderer) {
        this.labelRenderer.render(this.scene, this.camera)
      }
    }
  }
}
</script>

