___CSS_LOADER_EXPORT___.push([module.id, "\n.sub-model-container[data-v-3875025c] {\r\n  width: 100%;\r\n  height: 100%;\r\n  cursor: grab;\r\n  position: relative;\n}\n.sub-model-container[data-v-3875025c]:active {\r\n  cursor: grabbing;\n}\r\n", "",{"version":3,"sources":["webpack://./src/components/ThreeSubModel.vue"],"names":[],"mappings":";AA4mBA;EACA,WAAA;EACA,YAAA;EACA,YAAA;EACA,kBAAA;AACA;AAEA;EACA,gBAAA;AACA","sourcesContent":["<template>\r\n  <div class=\"sub-model-container\" ref=\"subModelContainer\"></div>\r\n</template>\r\n\r\n<script>\r\nimport * as THREE from 'three'\r\nimport { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'\r\n\r\nexport default {\r\n  name: 'ThreeSubModel',\r\n  props: {\r\n    floor: {\r\n      type: String,\r\n      required: true\r\n    },\r\n    sensorData: {\r\n      type: Array,\r\n      default: () => []\r\n    },\r\n    selectedSensorId: {\r\n      type: String,\r\n      default: null\r\n    },\r\n    // 接收自定义传感器信息\r\n    customSensorInfo: {\r\n      type: Object,\r\n      default: () => ({})\r\n    }\r\n  },\r\n  watch: {\r\n    floor(newFloor) {\r\n      this.updateModel(newFloor)\r\n    },\r\n    selectedSensorId(newId) {\r\n      if (newId) {\r\n        this.highlightSensor(newId)\r\n      }\r\n    }\r\n  },\r\n  data: function() {\r\n    return {\r\n      scene: null,\r\n      camera: null,\r\n      renderer: null,\r\n      controls: null,\r\n      currentModel: null,\r\n      sensors: [],\r\n      raycaster: null,\r\n      mouse: null,\r\n      selectedSensor: null,\r\n      // 与主模型相同的桥架类型分布\r\n      bridgeTypes: ['short', 'long', 'short', 'long', 'short', 'long', 'short', 'long']\r\n    }\r\n  },\r\n  mounted: function() {\r\n    this.initThree()\r\n    this.createModel(this.floor)\r\n    this.setupEventListeners()\r\n    this.animate()\r\n  },\r\n  beforeDestroy: function() {\r\n      if (this.renderer) {\r\n        this.renderer.dispose()\r\n      }\r\n      if (this.controls) {\r\n        this.controls.dispose()\r\n      }\r\n      window.removeEventListener('resize', this.onWindowResize)\r\n      this.$refs.subModelContainer.removeEventListener('mousedown', this.onMouseDown)\r\n      this.$refs.subModelContainer.removeEventListener('mousemove', this.onMouseMove)\r\n      \r\n      // 移除悬停信息显示元素\r\n      if (this.tooltip && this.tooltip.parentNode) {\r\n        this.tooltip.parentNode.removeChild(this.tooltip)\r\n      }\r\n    },\r\n  methods: {\r\n    initThree: function() {\r\n      // 获取容器尺寸\r\n      const container = this.$refs.subModelContainer\r\n      const width = container.clientWidth\r\n      const height = container.clientHeight\r\n      \r\n      // 创建场景\r\n      this.scene = new THREE.Scene()\r\n      this.scene.background = new THREE.Color(0xf0f0f0)\r\n      \r\n      // 创建相机\r\n      this.camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 1000)\r\n      this.camera.position.set(0, 14, 21)\r\n      \r\n      // 创建渲染器\r\n      this.renderer = new THREE.WebGLRenderer({ antialias: true })\r\n      this.renderer.setSize(width, height)\r\n      this.renderer.setPixelRatio(window.devicePixelRatio)\r\n      container.appendChild(this.renderer.domElement)\r\n      \r\n      // 创建控制器\r\n      this.controls = new OrbitControls(this.camera, this.renderer.domElement)\r\n      this.controls.enableDamping = true\r\n      this.controls.dampingFactor = 0.05\r\n      \r\n      // 添加光源\r\n      const ambientLight = new THREE.AmbientLight(0xffffff, 0.6)\r\n      this.scene.add(ambientLight)\r\n      \r\n      const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8)\r\n      directionalLight.position.set(10, 15, 10)\r\n      this.scene.add(directionalLight)\r\n      \r\n      // 创建射线投射器\r\n      this.raycaster = new THREE.Raycaster()\r\n      this.mouse = new THREE.Vector2()\r\n      \r\n      // 添加辅助坐标系\r\n      const axesHelper = new THREE.AxesHelper(5)\r\n      this.scene.add(axesHelper)\r\n    },\r\n    createModel(floor) {\r\n      // 清除旧模型\r\n      this.clearModel()\r\n      \r\n      // 根据楼层类型创建不同的模型\r\n      if (floor === 'top') {\r\n        this.createTopModel()\r\n      } else if (floor === 'pile') {\r\n        this.createPileModel()\r\n      } else {\r\n        this.createFloorModel(parseInt(floor))\r\n      }\r\n    },\r\n    createFloorModel(floorNumber) {\r\n      // 创建该楼层的圆柱切片\r\n      const geometry = new THREE.CylinderGeometry(10, 10, 1.5, 32)\r\n      const material = new THREE.MeshPhongMaterial({\r\n        color: 0xff9966,\r\n        transparent: true,\r\n        opacity: 1,\r\n        flatShading: false,\r\n        shininess: 80, // 增加金属度\r\n        specular: 0xffa500 // 增加高光颜色，增强金属质感\r\n      })\r\n      \r\n      this.currentModel = new THREE.Mesh(geometry, material)\r\n      this.currentModel.position.y = 0.75\r\n      this.scene.add(this.currentModel)\r\n      \r\n      // 添加楼层编号\r\n      this.addFloorLabel(floorNumber)\r\n      \r\n      // 添加该楼层的传感器\r\n      this.createFloorSensors(floorNumber)\r\n    },\r\n    createTopModel: function() {\r\n      // 创建库顶模型\r\n      const geometry = new THREE.CircleGeometry(10, 32)\r\n      const material = new THREE.MeshPhongMaterial({\r\n        color: 0x6699ff,\r\n        transparent: true,\r\n        opacity: 1,\r\n        flatShading: false,\r\n        shininess: 100, // 增加金属度\r\n        specular: 0x87cefa // 增加高光颜色，增强金属质感\r\n      })\r\n      \r\n      this.currentModel = new THREE.Mesh(geometry, material)\r\n      this.scene.add(this.currentModel)\r\n      \r\n      // 添加标签\r\n      this.addFloorLabel('库顶')\r\n      \r\n\r\n    },\r\n    createPileModel: function() {\r\n      // 创建桩基模型\r\n      const outerGeometry = new THREE.RingGeometry(10, 14, 32)\r\n      const innerGeometry = new THREE.CircleGeometry(10, 32)\r\n      const outerMaterial = new THREE.MeshPhongMaterial({\r\n        color: 0x996633,\r\n        transparent: true,\r\n        opacity: 1,\r\n        flatShading: false,\r\n        shininess: 60, // 增加金属度\r\n        specular: 0xd2b48c // 增加高光颜色，增强金属质感\r\n      })\r\n      const innerMaterial = new THREE.MeshPhongMaterial({\r\n        color: 0x996633,\r\n        transparent: true,\r\n        opacity: 1,\r\n        flatShading: false,\r\n        shininess: 60, // 增加金属度\r\n        specular: 0xd2b48c // 增加高光颜色，增强金属质感\r\n      })\r\n      \r\n      const outerRing = new THREE.Mesh(outerGeometry, outerMaterial)\r\n      const innerCircle = new THREE.Mesh(innerGeometry, innerMaterial)\r\n      \r\n      this.scene.add(outerRing)\r\n      this.scene.add(innerCircle)\r\n      \r\n      this.currentModel = outerRing\r\n      \r\n      // 添加标签\r\n      this.addFloorLabel('桩基')\r\n      \r\n\r\n    },\r\n    addFloorLabel(label) {\r\n      const canvas = document.createElement('canvas')\r\n      const context = canvas.getContext('2d')\r\n      context.font = 'Bold 30px Arial'\r\n      const metrics = context.measureText(label)\r\n      const textWidth = metrics.width\r\n      \r\n      canvas.width = textWidth + 20\r\n      canvas.height = 50\r\n      context.font = 'Bold 30px Arial'\r\n      context.fillStyle = 'rgba(0, 0, 0, 0.8)'\r\n      context.textAlign = 'center'\r\n      context.textBaseline = 'middle'\r\n      context.fillText(label, canvas.width / 2, canvas.height / 2)\r\n      \r\n      const texture = new THREE.CanvasTexture(canvas)\r\n      const spriteMaterial = new THREE.SpriteMaterial({ map: texture })\r\n      const sprite = new THREE.Sprite(spriteMaterial)\r\n      \r\n      sprite.scale.set(textWidth / 100, 50 / 100, 1)\r\n      sprite.position.set(0, 5, 0)\r\n      \r\n      this.scene.add(sprite)\r\n    },\r\n    createFloorSensors(floorNumber) {\r\n      // 创建不同的传感器几何体：竖向和横向\r\n      const horizontalSensorGeometry = new THREE.BoxGeometry(0.75, 0.3, 0.3)\r\n      const verticalSensorGeometry = new THREE.BoxGeometry(0.3, 0.75, 0.3)\r\n      const sensorMaterial = new THREE.MeshPhongMaterial({ \r\n        color: 0x2a9d8f, // 青绿色传感器\r\n        transparent: true,\r\n        opacity: 1,\r\n        shininess: 50,\r\n        emissive: 0x1a6d63, // 自发光效果\r\n        emissiveIntensity: 0.3\r\n      })\r\n      \r\n      // 创建蓝色传感器材质\r\n      const blueSensorMaterial = new THREE.MeshPhongMaterial({ \r\n        color: 0x0066ff, // 蓝色传感器\r\n        transparent: true,\r\n        opacity: 1,\r\n        shininess: 50,\r\n        emissive: 0x0033cc, // 自发光效果\r\n        emissiveIntensity: 0.3\r\n      })\r\n      \r\n      // 定义8个桥架位置，每个位置有左右两侧\r\n      const bridgePositions = [\r\n        {angle: 0, x: 15, z: 0},     // 右侧\r\n        {angle: Math.PI/4, x: 10.6, z: 10.6},  // 右上\r\n        {angle: Math.PI/2, x: 0, z: 15},      // 上侧\r\n        {angle: 3*Math.PI/4, x: -10.6, z: 10.6}, // 左上\r\n        {angle: Math.PI, x: -15, z: 0},       // 左侧\r\n        {angle: 5*Math.PI/4, x: -10.6, z: -10.6}, // 左下\r\n        {angle: 3*Math.PI/2, x: 0, z: -15},     // 下侧\r\n        {angle: 7*Math.PI/4, x: 10.6, z: -10.6}   // 右下\r\n      ]\r\n      \r\n      // 转换floorNumber为数字\r\n      const floor = parseInt(floorNumber) - 1 // 转为从0开始的索引\r\n      \r\n      // 遍历每个桥架\r\n      for (let bridgeIndex = 0; bridgeIndex < this.bridgeTypes.length; bridgeIndex++) {\r\n        const bridgeType = this.bridgeTypes[bridgeIndex]\r\n        const isLongBridge = bridgeType === 'long'\r\n        const position = bridgePositions[bridgeIndex]\r\n        const angle = position.angle\r\n        \r\n        // 计算桥架方向的垂直方向向量\r\n        const perpAngle1 = angle + Math.PI/2 // 右侧垂直方向\r\n        const perpAngle2 = angle - Math.PI/2 // 左侧垂直方向\r\n        \r\n        const bridgeWidth = 1 // 桥架宽度\r\n        const safeOffset = 1.5 // 减小安全偏移量，缩短间隔\r\n        const offsetDistance = (bridgeWidth/2 + safeOffset) / 2\r\n        \r\n        // 计算左右两侧位置\r\n        const leftX = 10 * Math.cos(angle) + offsetDistance * Math.cos(perpAngle1)\r\n        const leftZ = 10 * Math.sin(angle) + offsetDistance * Math.sin(perpAngle1)\r\n        \r\n        const rightX = 10 * Math.cos(angle) + offsetDistance * Math.cos(perpAngle2)\r\n        const rightZ = 10 * Math.sin(angle) + offsetDistance * Math.sin(perpAngle2)\r\n        \r\n        // 计算传感器Y坐标，将横向传感器放在楼层模型中间（Y=0.75），竖向传感器略低以避免重合\r\n        const horizontalY = 0.75 // 横向传感器位置（楼层中间）\r\n        const verticalY = 0 // 竖向传感器位置（向下偏移，避免与横向传感器重合）\r\n        \r\n        if (isLongBridge) {\r\n          // 长桥架逻辑\r\n          // 左侧每层一个横向传感器\r\n          const leftSensorId = `H${floorNumber}-B${bridgeIndex+1}-L`\r\n          if (this.customSensorInfo[leftSensorId]) {\r\n            const leftSensor = new THREE.Mesh(horizontalSensorGeometry, sensorMaterial.clone())\r\n              leftSensor.position.set(leftX, horizontalY, leftZ)\r\n              leftSensor.rotation.y = angle + 29*Math.PI/30\r\n              leftSensor.userData = {\r\n                id: leftSensorId,\r\n                floor: floorNumber,\r\n                bridge: bridgeIndex + 1,\r\n                side: 'left',\r\n                type: 'horizontal',\r\n                originalColor: 0x2a9d8f // 存储原始颜色\r\n              }\r\n            this.scene.add(leftSensor)\r\n            this.sensors.push(leftSensor)\r\n            this.addSensorLabel(leftSensor, `${bridgeIndex+1}-L`)\r\n          }\r\n          \r\n          // 右侧除第一层外每层一个竖向传感器\r\n          if (floor !== 0) {\r\n            const rightVerticalSensorId = `H${floorNumber}-B${bridgeIndex+1}-R-V`\r\n            if (this.customSensorInfo[rightVerticalSensorId]) {\r\n              const rightVerticalSensor = new THREE.Mesh(verticalSensorGeometry, sensorMaterial.clone())\r\n              rightVerticalSensor.position.set(rightX, verticalY, rightZ)\r\n              rightVerticalSensor.rotation.y = angle + Math.PI/30\r\n              rightVerticalSensor.userData = {\r\n                id: rightVerticalSensorId,\r\n                floor: floorNumber,\r\n                bridge: bridgeIndex + 1,\r\n                side: 'right',\r\n                type: 'vertical',\r\n                originalColor: 0x2a9d8f // 存储原始颜色\r\n              }\r\n              this.scene.add(rightVerticalSensor)\r\n              this.sensors.push(rightVerticalSensor)\r\n              this.addSensorLabel(rightVerticalSensor, `${bridgeIndex+1}-R-V`)\r\n            }\r\n          }\r\n          \r\n          // 右侧第1、3、4层各有一个横向传感器\r\n          if (floor === 0 || floor === 2 || floor === 3) { // 0=第1层，2=第3层，3=第4层\r\n            const rightHorizontalSensorId = `H${floorNumber}-B${bridgeIndex+1}-R-H`\r\n            if (this.customSensorInfo[rightHorizontalSensorId]) {\r\n              const rightHorizontalSensor = new THREE.Mesh(horizontalSensorGeometry, sensorMaterial.clone())\r\n              rightHorizontalSensor.position.set(rightX, horizontalY, rightZ)\r\n              rightHorizontalSensor.rotation.y = angle - 29*Math.PI/30\r\n              rightHorizontalSensor.userData = {\r\n                id: rightHorizontalSensorId,\r\n                floor: floorNumber,\r\n                bridge: bridgeIndex + 1,\r\n                side: 'right',\r\n                type: 'horizontal',\r\n                originalColor: 0x2a9d8f // 存储原始颜色\r\n              }\r\n              this.scene.add(rightHorizontalSensor)\r\n              this.sensors.push(rightHorizontalSensor)\r\n              this.addSensorLabel(rightHorizontalSensor, `${bridgeIndex+1}-R-H`)\r\n            }\r\n          }\r\n          \r\n          // 右侧第七层和第十六层各有一个蓝色横向传感器\r\n          if (floor === 6 || floor === 15) { // 6=第7层，15=第16层\r\n            const blueSensorId = `H${floorNumber}-B${bridgeIndex+1}-R-H`\r\n            if (this.customSensorInfo[blueSensorId]) {\r\n              const blueSensor = new THREE.Mesh(horizontalSensorGeometry, blueSensorMaterial.clone())\r\n              blueSensor.position.set(rightX, horizontalY, rightZ)\r\n              blueSensor.rotation.y = angle - 29*Math.PI/30\r\n              blueSensor.userData = {\r\n                id: blueSensorId,\r\n                floor: floorNumber,\r\n                bridge: bridgeIndex + 1,\r\n                side: 'right',\r\n                type: 'horizontal',\r\n                originalColor: 0x0066ff // 存储原始颜色\r\n              }\r\n              this.scene.add(blueSensor)\r\n              this.sensors.push(blueSensor)\r\n              this.addSensorLabel(blueSensor, `${bridgeIndex+1}-R-H`)\r\n            }\r\n          }\r\n        } else {\r\n          // 矮桥架逻辑\r\n          // 左侧只有1至9层有横向传感器\r\n          if (floor < 9) { // 只在0-8层创建（对应实际1-9层）\r\n            const leftSensorId = `H${floorNumber}-B${bridgeIndex+1}-L`\r\n            if (this.customSensorInfo[leftSensorId]) {\r\n              const leftSensor = new THREE.Mesh(horizontalSensorGeometry, sensorMaterial.clone())\r\n              leftSensor.position.set(leftX, horizontalY, leftZ)\r\n              leftSensor.rotation.y = angle - 16*Math.PI/30\r\n              leftSensor.userData = {\r\n                id: leftSensorId,\r\n                floor: floorNumber,\r\n                bridge: bridgeIndex + 1,\r\n                side: 'left',\r\n                type: 'horizontal',\r\n                originalColor: 0x2a9d8f // 存储原始颜色\r\n              }\r\n              this.scene.add(leftSensor)\r\n              this.sensors.push(leftSensor)\r\n              this.addSensorLabel(leftSensor, `${bridgeIndex+1}-L`)\r\n            }\r\n          }\r\n          \r\n          // 右侧只有第一层有一个横向传感器\r\n          if (floor === 0) {\r\n            const rightSensorId = `H${floorNumber}-B${bridgeIndex+1}-R`\r\n            if (this.customSensorInfo[rightSensorId]) {\r\n              const rightSensor = new THREE.Mesh(horizontalSensorGeometry, sensorMaterial.clone())\r\n              rightSensor.position.set(rightX, horizontalY, rightZ)\r\n              rightSensor.rotation.y = angle + 16*Math.PI/30\r\n              rightSensor.userData = {\r\n                id: rightSensorId,\r\n                floor: floorNumber,\r\n                bridge: bridgeIndex + 1,\r\n                side: 'right',\r\n                type: 'horizontal',\r\n                originalColor: 0x2a9d8f // 存储原始颜色\r\n              }\r\n              this.scene.add(rightSensor)\r\n              this.sensors.push(rightSensor)\r\n              this.addSensorLabel(rightSensor, `${bridgeIndex+1}-R`)\r\n            }\r\n          }\r\n        }\r\n      }\r\n    },\r\n\r\n\r\n    addSensorLabel(sensor, labelText) {\r\n      const canvas = document.createElement('canvas')\r\n      const context = canvas.getContext('2d')\r\n      context.font = '16px Arial'\r\n      const text = labelText.toString()\r\n      \r\n      // 测量文本宽度\r\n      const textWidth = context.measureText(text).width\r\n      // 根据文本宽度动态设置canvas大小\r\n      canvas.width = textWidth + 10 // 增加一些边距\r\n      canvas.height = 30\r\n      \r\n      context.fillStyle = 'rgba(0, 0, 0, 0.8)'\r\n      context.textAlign = 'center'\r\n      context.textBaseline = 'middle'\r\n      context.fillText(text, canvas.width / 2, canvas.height / 2)\r\n      \r\n      const texture = new THREE.CanvasTexture(canvas)\r\n      const spriteMaterial = new THREE.SpriteMaterial({ map: texture })\r\n      const sprite = new THREE.Sprite(spriteMaterial)\r\n      \r\n      // 根据文本长度调整标签大小\r\n      sprite.scale.set((textWidth + 10) / 100, 30 / 100, 1)\r\n      sprite.position.set(sensor.position.x, sensor.position.y + 0.5, sensor.position.z)\r\n      \r\n      this.scene.add(sprite)\r\n    },\r\n    clearModel: function() {\r\n      // 清除所有传感器\r\n      this.sensors.forEach(sensor => {\r\n        this.scene.remove(sensor)\r\n      })\r\n      this.sensors = []\r\n      \r\n      // 清除模型\r\n      if (this.currentModel) {\r\n        this.scene.remove(this.currentModel)\r\n        this.currentModel = null\r\n      }\r\n      \r\n      // 清除所有精灵对象（标签）\r\n      const sprites = []\r\n      this.scene.traverse(obj => {\r\n        if (obj.isSprite) {\r\n          sprites.push(obj)\r\n        }\r\n      })\r\n      sprites.forEach(sprite => {\r\n        this.scene.remove(sprite)\r\n      })\r\n    },\r\n    updateModel(floor) {\r\n      // 保存当前选中的传感器ID\r\n      const currentSelectedId = this.selectedSensor ? this.selectedSensor.userData.id : null\r\n      \r\n      // 创建新模型\r\n      this.createModel(floor)\r\n      \r\n      // 如果之前有选中的传感器，尝试在新模型中高亮它\r\n      if (currentSelectedId) {\r\n        this.highlightSensor(currentSelectedId)\r\n      }\r\n    },\r\n    setupEventListeners: function() {\r\n      window.addEventListener('resize', this.onWindowResize)\r\n      this.$refs.subModelContainer.addEventListener('mousedown', this.onMouseDown)\r\n      this.$refs.subModelContainer.addEventListener('mousemove', this.onMouseMove)\r\n      \r\n      // 创建悬停信息显示元素\r\n      this.tooltip = document.createElement('div')\r\n      this.tooltip.style.position = 'absolute'\r\n      this.tooltip.style.backgroundColor = 'rgba(0, 0, 0, 0.8)'\r\n      this.tooltip.style.color = 'white'\r\n      this.tooltip.style.padding = '8px 12px'\r\n      this.tooltip.style.borderRadius = '4px'\r\n      this.tooltip.style.fontSize = '14px'\r\n      this.tooltip.style.pointerEvents = 'none'\r\n      this.tooltip.style.zIndex = '1000'\r\n      this.tooltip.style.display = 'none'\r\n      document.body.appendChild(this.tooltip)\r\n    },\r\n    onWindowResize: function() {\r\n      const container = this.$refs.subModelContainer\r\n      const width = container.clientWidth\r\n      const height = container.clientHeight\r\n      \r\n      this.camera.aspect = width / height\r\n      this.camera.updateProjectionMatrix()\r\n      this.renderer.setSize(width, height)\r\n    },\r\n    onMouseMove: function(event) {\r\n      // 计算鼠标在归一化设备坐标系中的坐标 (-1 到 +1)\r\n      const rect = this.$refs.subModelContainer.getBoundingClientRect()\r\n      this.mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1\r\n      this.mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1\r\n      \r\n      // 更新射线投射器\r\n      this.raycaster.setFromCamera(this.mouse, this.camera)\r\n      \r\n  