// 通信服务，用于处理Vue应用与后端系统的交互
class CommunicationService {
  constructor() {
    // WebSocket连接实例
    this.socket = null;
    // 连接状态
    this.connected = false;
    // 消息队列，在连接建立前存储待发送的消息
    this.messageQueue = [];
    // 事件监听器映射
    this.eventListeners = {};
    // 默认的WebSocket服务器地址
    this.socketUrl = 'ws://localhost:8081'; // 实际部署时应从配置中获取
    // 连接超时时间（毫秒）
    this.connectTimeout = 5000;
    // 重连配置
    this.reconnectConfig = {
      maxAttempts: 5,
      currentAttempt: 0,
      delay: 1000,
      maxDelay: 30000
    };
  }

  /**
   * 初始化通信服务
   * @param {Object} options 配置选项
   * @param {string} options.socketUrl WebSocket服务器地址
   * @param {number} options.connectTimeout 连接超时时间
   */
  initialize(options = {}) {
    if (options.socketUrl) {
      this.socketUrl = options.socketUrl;
    }
    if (options.connectTimeout) {
      this.connectTimeout = options.connectTimeout;
    }
    
    this.connect();
  }

  /**
   * 连接到WebSocket服务器
   */
  connect() {
    if (this.connected || this.socket) {
      console.warn('WebSocket已经连接或正在连接中');
      return;
    }

    try {
      this.socket = new WebSocket(this.socketUrl);
      
      // 设置连接超时
      const timeoutId = setTimeout(() => {
        if (this.socket && this.socket.readyState === WebSocket.CONNECTING) {
          console.error('WebSocket连接超时');
          this.socket.close();
          this.handleConnectionError();
        }
      }, this.connectTimeout);

      this.socket.onopen = (event) => {
        clearTimeout(timeoutId);
        console.log('WebSocket连接已建立');
        this.connected = true;
        this.reconnectConfig.currentAttempt = 0;
        
        // 触发连接建立事件
        this.emit('connected');
        
        // 发送队列中的消息
        this.flushMessageQueue();
      };

      this.socket.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);
          this.handleMessage(data);
        } catch (error) {
          console.error('解析WebSocket消息失败:', error);
        }
      };

      this.socket.onerror = (error) => {
        clearTimeout(timeoutId);
        console.error('WebSocket连接错误:', error);
        this.handleConnectionError();
      };

      this.socket.onclose = (event) => {
        clearTimeout(timeoutId);
        console.log('WebSocket连接已关闭:', event.code, event.reason);
        this.connected = false;
        this.socket = null;
        
        // 触发连接关闭事件
        this.emit('disconnected', { code: event.code, reason: event.reason });
        
        // 尝试重连
        this.attemptReconnect();
      };
    } catch (error) {
      console.error('创建WebSocket连接失败:', error);
      this.handleConnectionError();
    }
  }

  /**
   * 处理连接错误
   */
  handleConnectionError() {
    this.connected = false;
    this.socket = null;
    this.attemptReconnect();
  }

  /**
   * 尝试重连
   */
  attemptReconnect() {
    if (this.reconnectConfig.currentAttempt >= this.reconnectConfig.maxAttempts) {
      console.error(`达到最大重连次数 ${this.reconnectConfig.maxAttempts}，停止重连`);
      this.emit('maxReconnectAttemptsReached', { maxAttempts: this.reconnectConfig.maxAttempts });
      return;
    }

    this.reconnectConfig.currentAttempt++;
    const delay = Math.min(
      this.reconnectConfig.delay * Math.pow(2, this.reconnectConfig.currentAttempt - 1),
      this.reconnectConfig.maxDelay
    );

    console.log(`将在 ${delay}ms 后进行第 ${this.reconnectConfig.currentAttempt} 次重连`);
    
    setTimeout(() => {
      console.log(`尝试第 ${this.reconnectConfig.currentAttempt} 次重连...`);
      this.connect();
    }, delay);
  }

  /**
   * 发送消息到服务器
   * @param {Object} message 要发送的消息对象
   * @returns {Promise} 发送操作的Promise
   */
  send(message) {
    return new Promise((resolve, reject) => {
      const messageWithId = {
        id: this.generateMessageId(),
        timestamp: new Date().toISOString(),
        ...message
      };

      if (this.connected && this.socket && this.socket.readyState === WebSocket.OPEN) {
        try {
          this.socket.send(JSON.stringify(messageWithId));
          resolve(messageWithId);
        } catch (error) {
          console.error('发送消息失败:', error);
          reject(error);
        }
      } else {
        console.warn('WebSocket未连接，将消息加入队列');
        this.messageQueue.push({ message: messageWithId, resolve, reject });
        // 尝试重新连接
        if (!this.socket) {
          this.connect();
        }
      }
    });
  }

  /**
   * 发送命令到服务器
   * @param {string} command 命令名称
   * @param {Object} params 命令参数
   * @returns {Promise} 命令发送操作的Promise
   */
  sendCommand(command, params = {}) {
    return this.send({
      type: 'command',
      command,
      params
    });
  }

  /**
   * 发送查询请求到服务器
   * @param {string} query 查询类型
   * @param {Object} params 查询参数
   * @returns {Promise} 查询操作的Promise
   */
  sendQuery(query, params = {}) {
    return this.send({
      type: 'query',
      query,
      params
    });
  }

  /**
   * 处理接收到的消息
   * @param {Object} message 接收到的消息对象
   */
  handleMessage(message) {
    // 检查消息类型
    if (!message.type) {
      console.warn('接收到的消息没有类型:', message);
      return;
    }

    // 处理不同类型的消息
    switch (message.type) {
      case 'command_response':
        this.handleCommandResponse(message);
        break;
      case 'query_response':
        this.handleQueryResponse(message);
        break;
      case 'event':
        this.handleEvent(message);
        break;
      case 'error':
        this.handleError(message);
        break;
      default:
        console.warn('未知的消息类型:', message.type);
        break;
    }
  }

  /**
   * 处理命令响应
   * @param {Object} response 命令响应对象
   */
  handleCommandResponse(response) {
    console.log('收到命令响应:', response);
    this.emit('command_response', response);
  }

  /**
   * 处理查询响应
   * @param {Object} response 查询响应对象
   */
  handleQueryResponse(response) {
    console.log('收到查询响应:', response);
    this.emit('query_response', response);
  }

  /**
   * 处理事件通知
   * @param {Object} event 事件对象
   */
  handleEvent(event) {
    console.log('收到事件通知:', event);
    // 触发特定事件
    if (event.eventName) {
      this.emit(event.eventName, event.data);
    }
    // 同时触发通用事件
    this.emit('event', event);
  }

  /**
   * 处理错误消息
   * @param {Object} error 错误对象
   */
  handleError(error) {
    console.error('收到错误消息:', error);
    this.emit('error', error);
  }

  /**
   * 刷新消息队列，发送所有待发送的消息
   */
  flushMessageQueue() {
    console.log(`正在发送队列中的 ${this.messageQueue.length} 条消息`);
    
    while (this.messageQueue.length > 0) {
      const queueItem = this.messageQueue.shift();
      try {
        this.socket.send(JSON.stringify(queueItem.message));
        queueItem.resolve(queueItem.message);
      } catch (error) {
        console.error('发送队列中的消息失败:', error);
        queueItem.reject(error);
      }
    }
  }

  /**
   * 生成唯一的消息ID
   * @returns {string} 唯一消息ID
   */
  generateMessageId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
  }

  /**
   * 添加事件监听器
   * @param {string} eventName 事件名称
   * @param {Function} listener 事件监听器函数
   */
  on(eventName, listener) {
    if (!this.eventListeners[eventName]) {
      this.eventListeners[eventName] = [];
    }
    this.eventListeners[eventName].push(listener);
  }

  /**
   * 移除事件监听器
   * @param {string} eventName 事件名称
   * @param {Function} listener 要移除的事件监听器函数（可选，如果不提供则移除该事件的所有监听器）
   */
  off(eventName, listener) {
    if (!this.eventListeners[eventName]) {
      return;
    }

    if (!listener) {
      // 移除所有该事件的监听器
      delete this.eventListeners[eventName];
    } else {
      // 移除指定的监听器
      this.eventListeners[eventName] = this.eventListeners[eventName].filter(l => l !== listener);
    }
  }

  /**
   * 触发事件
   * @param {string} eventName 事件名称
   * @param {*} data 事件数据
   */
  emit(eventName, data) {
    if (!this.eventListeners[eventName]) {
      return;
    }

    this.eventListeners[eventName].forEach(listener => {
      try {
        listener(data);
      } catch (error) {
        console.error(`事件监听器执行错误 (${eventName}):`, error);
      }
    });
  }

  /**
   * 断开WebSocket连接
   */
  disconnect() {
    console.log('正在关闭WebSocket连接...');
    
    // 清空消息队列，拒绝所有待发送的消息
    while (this.messageQueue.length > 0) {
      const queueItem = this.messageQueue.shift();
      queueItem.reject(new Error('连接已关闭'));
    }

    // 重置重连配置
    this.reconnectConfig.currentAttempt = 0;

    // 关闭WebSocket连接
    if (this.socket) {
      this.socket.close();
      this.socket = null;
    }

    this.connected = false;
  }

  /**
   * 获取连接状态
   * @returns {boolean} 连接状态
   */
  getConnectionStatus() {
    return this.connected;
  }
}

// 导出单例实例
const communicationService = new CommunicationService();
export default communicationService;
